#include <cstdlib>
#include <cstring>

extern "C"
{
#include "logger.h"
#include "ble_priv.h"
#include "esp_rom_crc.h"
}

static const char *TAG = "bleRcvMsg";

static ble_rcv_msg_t g_rcv = {
    .allocated = 0,
    .offset = 0,
    .brace_depth = 0,
    .receiving = false,
    .buffer = NULL,
    .expected_seq = 0,
    .total_chunks = 0,
    .total_len = 0,
    .expected_crc32 = 0,
};

static int realloc_buffer(size_t needed)
{
    if (g_rcv.buffer == NULL) {
        size_t init_size = 512;
        if (needed > init_size) {
            init_size = needed;
        }

        g_rcv.buffer = (uint8_t *)malloc(init_size);
        if (!g_rcv.buffer) {
            ESP_LOG_E(TAG, "malloc failed");
            return -1;
        }

        g_rcv.allocated = init_size;
    }

    if (needed > g_rcv.allocated) {
        size_t new_size = g_rcv.allocated * 2;
        while (new_size < needed) {
            new_size *= 2;
        }

        uint8_t *tmp = (uint8_t *)realloc(g_rcv.buffer, new_size);
        if (!tmp) {
            ESP_LOG_E(TAG, "realloc failed needed=%u", (unsigned)new_size);
            return -1;
        }

        g_rcv.buffer = tmp;
        g_rcv.allocated = new_size;
    }

    return 0;
}

static int parse_chunk_header(const uint8_t *buf, size_t len,
                              uint32_t *seq, uint32_t *n, size_t *total_len, uint32_t *crc32, char *flag,
                              size_t *payload_offset)
{
    if (buf == NULL || len < 30) {
        return -1;
    }

    const char *p = (const char *)buf;
    const char *end = (const char *)buf + len;

    if (end - p < 4 || memcmp(p, "SEQ=", 4) != 0) {
        return -1;
    }
    p += 4;
    char *e;
    unsigned long v = strtoul(p, &e, 10);
    if (e == p || v > 0xFFFFu) {
        return -1;
    }
    *seq = (uint32_t)v;
    p = e;

    if ((size_t)(end - p) < 3 || memcmp(p, ";N=", 3) != 0) {
        return -1;
    }
    p += 3;
    v = strtoul(p, &e, 10);
    if (e == p || v == 0 || v > 0xFFFFu) {
        return -1;
    }
    *n = (uint32_t)v;
    p = e;

    if ((size_t)(end - p) < 5 || memcmp(p, ";LEN=", 5) != 0) {
        return -1;
    }
    p += 5;
    v = strtoul(p, &e, 10);
    if (e == p || v > SFY_CONFIG_MAX_SIZE) {
        return -1;
    }
    *total_len = (size_t)v;
    p = e;

    if ((size_t)(end - p) < 5 || memcmp(p, ";CRC=", 5) != 0) {
        return -1;
    }
    p += 5;
    if ((size_t)(end - p) < 8) {
        return -1;
    }
    v = strtoul(p, &e, 16);
    if (e != p + 8) {
        return -1;
    }
    *crc32 = (uint32_t)v;
    p = e;

    if ((size_t)(end - p) < 4 || memcmp(p, ";F=", 3) != 0) {
        return -1;
    }
    p += 3;
    char f = *p;
    if (f != 'S' && f != 'E' && f != '-') {
        return -1;
    }
    *flag = f;
    p++;
    if (p >= end || *p != ';') {
        return -1;
    }
    p++;
    *payload_offset = (size_t)(p - (const char *)buf);
    return 0;
}

void rcvMsg_reset(void)
{
    if (g_rcv.buffer) {
        free(g_rcv.buffer);
        g_rcv.buffer = NULL;
    }

    g_rcv.offset = 0;
    g_rcv.allocated = 0;
    g_rcv.brace_depth = 0;
    g_rcv.receiving = false;
    g_rcv.expected_seq = 0;
    g_rcv.total_chunks = 0;
    g_rcv.total_len = 0;
    g_rcv.expected_crc32 = 0;
}

int rcvMsg_feed(const uint8_t *chunk, size_t incoming_len, bool *is_complete)
{
    uint32_t seq = 0;
    uint32_t n = 0;
    size_t total_len = 0;
    size_t payload_offset = 0;
    uint32_t expected_crc32 = 0;
    char flag = 0;

    if (parse_chunk_header(chunk, incoming_len,
                           &seq, &n, &total_len, &expected_crc32, &flag,
                           &payload_offset) != 0) {
        ESP_LOG_E(TAG, "BLE - ERROR: invalid chunk header");
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    size_t payload_len = incoming_len - payload_offset;
    const uint8_t *payload = chunk + payload_offset;

    if (!g_rcv.receiving) {
        bool valid_first = (seq == 0) && (flag == 'S' || (flag == 'E' && n == 1));
        if (!valid_first) {
            ESP_LOG_E(TAG, "BLE - ERROR: first chunk must be SEQ=0 with F=S or F=E (if N=1)");
            rcvMsg_reset();
            return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
        }
        if (total_len > SFY_CONFIG_MAX_SIZE) {
            ESP_LOG_E(TAG, "BLE - ERROR: LEN %u exceeds SFY_CONFIG_MAX_SIZE", (unsigned)total_len);
            rcvMsg_reset();
            return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
        }
        g_rcv.total_chunks = n;
        g_rcv.total_len = total_len;
        g_rcv.expected_crc32 = expected_crc32;
        g_rcv.expected_seq = 1;
        g_rcv.receiving = true;
    } else {
        if (seq != g_rcv.expected_seq) {
            ESP_LOG_E(TAG, "BLE - ERROR: out-of-order chunk: expected SEQ=%u got %u",
                     (unsigned)g_rcv.expected_seq, (unsigned)seq);
            rcvMsg_reset();
            return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
        }
        g_rcv.expected_seq++;
    }

    size_t needed_size = g_rcv.offset + payload_len;
    if (needed_size > g_rcv.total_len) {
        ESP_LOG_E(TAG, "BLE - ERROR: payload overflow: offset=%u + payload=%u > LEN=%u",
                 (unsigned)g_rcv.offset, (unsigned)payload_len, (unsigned)g_rcv.total_len);
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    if (realloc_buffer(needed_size + 1) < 0) {
        rcvMsg_reset();
        return BLE_ATT_ERR_UNLIKELY;
    }

    memcpy(&g_rcv.buffer[g_rcv.offset], payload, payload_len);
    g_rcv.offset += payload_len;

    if (flag != 'E') {
        ESP_LOGN(TAG, "BLE - fragment OK | seq = %u/%u | received = %u bytes | total = %u",
                 (unsigned)(seq + 1), (unsigned)g_rcv.total_chunks, (unsigned)payload_len, (unsigned)g_rcv.offset);
        if (is_complete) {
            *is_complete = false;
        }
        return 0;
    }

    if (g_rcv.offset != g_rcv.total_len) {
        ESP_LOG_E(TAG, "BLE - ERROR: F=E but length mismatch: have %u expected %u",
                 (unsigned)g_rcv.offset, (unsigned)g_rcv.total_len);
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    uint32_t computed_crc = esp_rom_crc32_le(0xFFFFFFFFu, g_rcv.buffer, g_rcv.offset);
    if (computed_crc != g_rcv.expected_crc32) {
        ESP_LOG_E(TAG, "BLE - ERROR: CRC mismatch: computed=0x%08lX expected=0x%08lX",
                 (unsigned long)computed_crc, (unsigned long)g_rcv.expected_crc32);
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    if (g_rcv.buffer[0] != '{') {
        ESP_LOG_E(TAG, "BLE - ERROR: JSON does not start with '{'");
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    g_rcv.buffer[g_rcv.offset] = '\0';
    ESP_LOGN(TAG, "BLE - received %sCOMPLETED%s | total = %u bytes | chunks = %u",
             LOG_COLOR_G, LOG_RESET_COLOR, (unsigned)g_rcv.offset, (unsigned)g_rcv.total_chunks);

    if (is_complete) {
        *is_complete = true;
    }
    return 0;
}

uint8_t *rcvMsg_buffer(void)
{
    return g_rcv.buffer;
}

size_t rcvMsg_len(void)
{
    return g_rcv.offset;
}

