#ifndef BLE_PRIV_H
#define BLE_PRIV_H

#include "ble.h"
#include "ble_port.h"

#define SFY_CONFIG_MAX_SIZE         1500
#define INDICATE_TX_MAX_RETRIES     5
/** Máximo tamaño de cabecera por chunk: SEQ=<seq>;N=<n>;LEN=<len>;CRC=<hex8>;F=<S|E|->; */
#define BLE_INDICATE_CHUNK_HEADER_MAX  52
#define BLE_INDICATE_MAX_CHUNK_PAYLOAD 128

typedef uint8_t *(*ble_indicate_next_msg_fn)(size_t *len);
typedef uint8_t *(*ble_notify_next_msg_fn)(size_t *len);

typedef struct {
    /* characteristic / subscription */
    uint16_t attr_handle;
    uint16_t conn_handle;
    bool enabled;

    /* tx state */
    uint8_t  *tosend_buf;
    size_t    tosend_len;
    size_t    tosend_offset;
    uint8_t   tosend_retries;
    bool      active;
    size_t    tosend_chunk;

    /* next message provider */
    ble_indicate_next_msg_fn next_msg_cb;

    /* send event */
    struct ble_npl_event send_event;

    /* fragment */
    bool fragment;
    size_t num_chunks;
    size_t chunk_len;
    uint32_t crc32;
} ble_indicate_ctx_t;

typedef struct {
    uint16_t attr_handle;
    uint16_t conn_handle;
    bool enabled;

    /* throttled send */
    struct ble_npl_callout callout;
    bool active;
    uint32_t interval_ms;
    uint8_t max_per_interval;
    ble_notify_next_msg_fn next_msg_cb;
} ble_notify_ctx_t;

/** Flag de chunk: S=start, E=end, -=intermedio */
typedef enum {
    CHUNK_FLAG_START = 'S',
    CHUNK_FLAG_END   = 'E',
    CHUNK_FLAG_MID   = '-',
} ble_chunk_flag_t;

typedef struct {
    size_t allocated;
    size_t offset;
    int brace_depth;
    bool receiving;
    uint8_t* buffer;
    /* Verificación de paquete: SEQ=;N=;LEN=;CRC=;F=;<payload> */
    uint32_t expected_seq;   /* próximo SEQ esperado (0..N-1) */
    uint32_t total_chunks;
    size_t   total_len;      /* LEN = bytes totales del JSON */
    uint32_t expected_crc32; /* CRC del JSON completo */
} ble_rcv_msg_t;

int getVerb(void);

esp_err_t ble_start(void);
esp_err_t ble_stop(void);
void ble_lifecycle_lock(void);
void ble_lifecycle_unlock(void);

int ble_gap_service_init(char* name);
void adv_init(void);
void ble_gap_shutdown(void);
void ble_gap_update_adv_payload(void);

int gatt_svc_init(void);
void gatt_svr_register_cb(struct ble_gatt_register_ctxt *ctxt, void *arg);
void gatt_svr_subscribe_cb(struct ble_gap_event *event);

void ble_indicate_handler(uint16_t handle, int status);

void rcvMsg_reset(void);
int rcvMsg_feed(const uint8_t *chunk, size_t incoming_len, bool *is_complete);
uint8_t *rcvMsg_buffer(void);
size_t rcvMsg_len(void);

// params
esp_err_t process_sfy_config_json(const char *json_str,
                               size_t len,
                               char **ret_buf);
esp_err_t read_sfy_config_json(char **out_buffer);

// history
uint8_t* get_data_from_storage(size_t *len);
uint8_t* get_data_from_ram(size_t *len);
void confirm_datapoint_send();
void cancel_history_send();
void confirm_history_send();

// logs
uint8_t* get_log(size_t *len);
uint8_t* get_logTerminal(size_t *len);
esp_err_t ble_notify_send_logControl(const uint8_t *data, size_t len);
void ble_logTerminal_capture_enable(void);
void ble_logTerminal_capture_disable(void);

// metadata
uint8_t* ble_getMetadata(size_t *len);
uint8_t* ble_getDiagnosis(size_t *len);

// commands
void ble_process_cloud_command(char* message, size_t len);
esp_err_t comm_execute(uint16_t cmd, uint64_t value, char* buffer);

#endif

