/* Buffer para manufacturer data; se rellena con get_data_from_ram y se actualiza periódicamente */
static uint8_t mfg_buf[MFG_DATA_MAX];
static uint8_t mfg_len = 0;
static uint8_t adv_indicator = 0;
static bool mfg_force_refresh_from_cache = false;

typedef struct {
    bool include_mfg_data;
    bool include_scan_rsp_name;
    uint16_t adv_itvl_min_ms;
    uint16_t adv_itvl_max_ms;
    const char *label;
} adv_profile_t;

void ble_set_adv_indicator(uint8_t value) {
    if(value == adv_indicator) return;

    ESP_LOG_I(TAG, "Setting adv indicator to %d", value);
    adv_indicator = (value != 0) ? 1 : 0;
    mfg_force_refresh_from_cache = true;
}

inline static void format_addr(char *addr_str, uint8_t addr[]) {
    sprintf(addr_str, "%02X:%02X:%02X:%02X:%02X:%02X", addr[0], addr[1],
            addr[2], addr[3], addr[4], addr[5]);
}

static void start_advertising(void);
static void print_conn_info(struct ble_gap_conn_desc *desc, int verb);
static int gap_event_handler(struct ble_gap_event *event, void *arg);

static adv_profile_t get_adv_profile(void) {
    adv_profile_t profile = {
        .include_mfg_data = false,
        .include_scan_rsp_name = true,
        .adv_itvl_min_ms = 500,
        .adv_itvl_max_ms = 510,
        .label = "ADV_LINK",
    };

    switch (ble_get_app_link()) {
        case APP_LINK_ADV_DATA_LINK:
            profile.include_mfg_data = true;
            profile.include_scan_rsp_name = true;
            profile.adv_itvl_min_ms = 500;
            profile.adv_itvl_max_ms = 510;
            profile.label = "ADV_DATA_LINK";
            break;
        case APP_LINK_ADV_LINK:
            profile.include_mfg_data = false;
            profile.include_scan_rsp_name = true;
            profile.adv_itvl_min_ms = 500;
            profile.adv_itvl_max_ms = 510;
            profile.label = "ADV_LINK";
            break;
        case APP_LINK_LINK:
            profile.include_mfg_data = false;
            profile.include_scan_rsp_name = false;
            profile.adv_itvl_min_ms = APP_LINK_LINK_ADV_ITVL_MIN_MS;
            profile.adv_itvl_max_ms = APP_LINK_LINK_ADV_ITVL_MAX_MS;
            profile.label = "LINK";
            break;
        case APP_LINK_DISABLED:
        default:
            profile.include_mfg_data = false;
            profile.include_scan_rsp_name = true;
            profile.adv_itvl_min_ms = 500;
            profile.adv_itvl_max_ms = 510;
            profile.label = "DISABLED";
            break;
    }

    return profile;
}

/**
 * Actualiza mfg_buf/mfg_len con los datos devueltos por get_data_from_ram.
 * Si get_data_from_ram devuelve NULL, no se modifica nada (no se tocan los adv fields).
 * @return true si el contenido cambió y se actualizó mfg_buf/mfg_len; false si no hubo cambios.
 */
static bool update_mfg_from_ram(void) {
    size_t len = 0;
    uint8_t *p = get_data_from_ram(&len);
    if (p != NULL && len > 0) {
        const size_t max_payload_len = (size_t)MFG_DATA_MAX - 1;
        size_t copy_len = (len > max_payload_len) ? max_payload_len : len;
        uint8_t candidate_len = (uint8_t)(copy_len + 1);
        uint8_t candidate_buf[MFG_DATA_MAX];
        memcpy(candidate_buf, p, copy_len);
        candidate_buf[copy_len] = adv_indicator;

        /* No setear nada si el paquete no cambió */
        if (mfg_len == candidate_len && memcmp(mfg_buf, candidate_buf, candidate_len) == 0) {
            delete[] p;
            return false;
        }
        memcpy(mfg_buf, candidate_buf, candidate_len);
        mfg_len = candidate_len;
        delete[] p;
        return true;
    } else if(mfg_force_refresh_from_cache) {
        ESP_LOG_I(TAG, "Force refresh from cache");
        mfg_force_refresh_from_cache = false;
        if (mfg_len == 0) {
            return false;
        }
        uint8_t idx = mfg_len - 1;
        if (mfg_buf[idx] == adv_indicator) {
            return false;
        }
        mfg_buf[idx] = adv_indicator;
        return true;
    }
    /* get_data_from_ram devolvió NULL: no tocar mfg_buf/mfg_len ni los adv fields */
    return false;
}

/**
 * @brief Inicializa la capa GAP del stack BLE y configura el nombre del dispositivo.
 *
 * @param name Nombre del dispositivo
 * @return 0 en caso de exito o un codigo de error si falla al establecer el nombre
 */
int ble_gap_service_init(char* name) {
    int rc = 0;

    // Inicializo GAP
    ble_svc_gap_init();

    // Seteo device name
    rc = ble_svc_gap_device_name_set(name);
    if (rc != 0) {
        ESP_LOG_E(TAG, "ERROR: Failed to set device name to '%s' [err: %d]",
                 name, rc);
        return rc;
    }

    ble_scanner_set_device_name(name);

    return rc;
}

void adv_init(void) {
    int rc = 0;
    char addr_str[18] = {0};

    // Verifica que el dispositivo tiene una BT Identity Address (direccion bluetooth "oficial"). Equivalente a la MAC address pero para BLE.
    // Si no la tiene intenta crearla
    rc = ble_hs_util_ensure_addr(0);
    if (rc != 0) {
        ESP_LOG_E(TAG, "ERROR: Device does not have any available BT address!");
        return;
    }

    // Setea el tipo de address que se usa para GAP (publica y random estatica). Se guarda en own_addr_type
    rc = ble_hs_id_infer_auto(0, &own_addr_type);
    if (rc != 0) {
        ESP_LOG_E(TAG, "ERROR: Failed to infer address type [err: %d]", rc);
        return;
    }

    // Copia y printea la address
    rc = ble_hs_id_copy_addr(own_addr_type, addr_val, NULL);
    if (rc != 0) {
        ESP_LOG_E(TAG, "ERROR: Failed to copy device address [err: %d]", rc);
        return;
    }
    format_addr(addr_str, addr_val);
    ESP_LOGN(TAG, "Starting ADV... Device address: %s", addr_str);

    ble_scanner_init();

    // start -> Aca es donde el device empieza a "existir" para el mundo exterior
    start_advertising();

    /* Escucha ADV externos sin alterar el ADV/scan response propio */
    ble_scanner_start(own_addr_type, gap_event_handler);
}

void ble_gap_shutdown(void) {
    ble_scanner_stop();

    int rc = ble_gap_adv_stop();
    if (rc != 0 && rc != BLE_HS_EALREADY && rc != BLE_HS_EINVAL) {
        ESP_LOG_W(TAG, "BLE - Failed to stop ADV [rc: %d]", rc);
    }

    if (active_conn_handle != BLE_HS_CONN_HANDLE_NONE) {
        struct ble_gap_conn_desc desc;
        rc = ble_gap_conn_find(active_conn_handle, &desc);
        if (rc == 0) {
            rc = ble_gap_terminate(active_conn_handle, BLE_ERR_REM_USER_CONN_TERM);
            if (rc != 0 && rc != BLE_HS_ENOTCONN && rc != BLE_HS_EALREADY) {
                ESP_LOG_W(TAG, "BLE - Failed to terminate connection [rc: %d]", rc);
            }
        } else if (rc != BLE_HS_ENOTCONN) {
            ESP_LOG_W(TAG, "BLE - Failed to query active connection [rc: %d]", rc);
        }
        active_conn_handle = BLE_HS_CONN_HANDLE_NONE;
    }
}

void ble_gap_update_adv_payload(void) {
    if (!ble_gap_adv_active()) {
        ESP_LOG_W(TAG, "BLE - ADV payload update skipped: ADV not active");
        return;
    }

    adv_profile_t profile = get_adv_profile();
    ESP_LOG_I(TAG,
             "BLE - ADV payload update: profile=%s interval=%u-%u ms mfg=%d name=%d",
             profile.label,
             profile.adv_itvl_min_ms,
             profile.adv_itvl_max_ms,
             (int)profile.include_mfg_data,
             (int)profile.include_scan_rsp_name);

    struct ble_hs_adv_fields adv_fields;
    struct ble_hs_adv_fields rsp_fields;
    memset(&adv_fields, 0, sizeof(adv_fields));
    memset(&rsp_fields, 0, sizeof(rsp_fields));
    adv_fields.flags = BLE_HS_ADV_F_DISC_GEN | BLE_HS_ADV_F_BREDR_UNSUP;

    if (profile.include_mfg_data) {
        update_mfg_from_ram();
        if (mfg_len > 0) {
            adv_fields.mfg_data = mfg_buf;
            adv_fields.mfg_data_len = mfg_len;
        }
    }

    int rc = ble_gap_adv_set_fields(&adv_fields);
    if (rc != 0) {
        ESP_LOG_W(TAG, "BLE - Failed to update ADV payload [rc: %d]", rc);
        return;
    }

    if (profile.include_scan_rsp_name) {
        const char *name = ble_svc_gap_device_name();
        rsp_fields.name = (uint8_t *)name;
        rsp_fields.name_len = strlen(name);
        rsp_fields.name_is_complete = 1;
    }

    rc = ble_gap_adv_rsp_set_fields(&rsp_fields);
    if (rc != 0) {
        ESP_LOG_W(TAG, "BLE - Failed to update scan response [rc: %d]", rc);
    }
}

