typedef enum {
    BLE_STATE_STOPPED = 0,
    BLE_STATE_STARTING,
    BLE_STATE_STARTED,
    BLE_STATE_STOPPING,
} ble_runtime_state_t;

static ble_runtime_state_t s_ble_state = BLE_STATE_STOPPED;

static const char *ble_state_to_str(ble_runtime_state_t state) {
    switch (state) {
        case BLE_STATE_STOPPED:  return "STOPPED";
        case BLE_STATE_STARTING: return "STARTING";
        case BLE_STATE_STARTED:  return "STARTED";
        case BLE_STATE_STOPPING: return "STOPPING";
        default:                 return "UNKNOWN";
    }
}

static esp_err_t ble_lifecycle_mutex_init(void) {
    if (s_ble_lifecycle_mutex != NULL) {
        return ESP_OK;
    }

    s_ble_lifecycle_mutex = xSemaphoreCreateRecursiveMutex();
    if (s_ble_lifecycle_mutex == NULL) {
        ESP_LOG_E(TAG, "ERROR: Failed to create BLE lifecycle mutex");
        return ESP_ERR_NO_MEM;
    }

    return ESP_OK;
}

void ble_lifecycle_lock(void) {
    if (ble_lifecycle_mutex_init() != ESP_OK) {
        return;
    }

    xSemaphoreTakeRecursive(s_ble_lifecycle_mutex, portMAX_DELAY);
}

void ble_lifecycle_unlock(void) {
    if (s_ble_lifecycle_mutex == NULL) {
        return;
    }

    xSemaphoreGiveRecursive(s_ble_lifecycle_mutex);
}

int getVerb(void) {
    return verb;
}

