static void nimble_host_task(void *param) {
    /* Task entry log */
    ESP_LOGN(TAG, "BLE host started (fh: %d)", xPortGetFreeHeapSize());

    /* This function won't return until nimble_port_stop() is executed */
    nimble_port_run();

    /* Clean up at exit */
    s_nimble_host_task_handle = NULL;
    vTaskDelete(NULL);
}

