void ble_init(uint64_t device_id) {
    if (ble_lifecycle_mutex_init() != ESP_OK) {
        return;
    }

    ble_lifecycle_lock();
    s_device_id = device_id;
    s_ble_init_done = true;
    ESP_LOG_I(TAG, "BLE init: device_id=%" PRIu64 " state=%s", s_device_id, ble_state_to_str(s_ble_state));

    if (ble_get_app_link() == APP_LINK_DISABLED) {
        ESP_LOGN(TAG, "BLE init skipped (app_link=APP_LINK_DISABLED)");
        ble_lifecycle_unlock();
        return;
    }

    (void)ble_start();
    ble_lifecycle_unlock();
}

esp_err_t ble_start(void) {
    ble_lifecycle_lock();

    if (!s_ble_init_done) {
        ESP_LOG_W(TAG, "BLE start ignored: ble_init not called (state=%s)", ble_state_to_str(s_ble_state));
        ble_lifecycle_unlock();
        return ESP_ERR_INVALID_STATE;
    }

    if (s_ble_state == BLE_STATE_STARTED || s_ble_started) {
        ble_lifecycle_unlock();
        return ESP_OK;
    }

    if (s_ble_state == BLE_STATE_STARTING || s_ble_state == BLE_STATE_STOPPING) {
        ESP_LOG_W(TAG, "BLE start denied: transition in progress (state=%s)", ble_state_to_str(s_ble_state));
        ble_lifecycle_unlock();
        return ESP_ERR_INVALID_STATE;
    }

    if (ble_get_app_link() == APP_LINK_DISABLED) {
        ESP_LOGN(TAG, "BLE start skipped (app_link=APP_LINK_DISABLED state=%s)", ble_state_to_str(s_ble_state));
        ble_lifecycle_unlock();
        return ESP_OK;
    }

    s_ble_state = BLE_STATE_STARTING;
    ESP_LOG_I(TAG, "BLE transition: %s -> %s", ble_state_to_str(BLE_STATE_STOPPED), ble_state_to_str(s_ble_state));

    /* Local variables */
    int rc = 0;
    esp_err_t ret = ESP_OK;

    ESP_LOGN(TAG,"--------------------- sfy-BLE ---------------------");
    ESP_LOGN(TAG,"BLE start... (fh = %db)",xPortGetFreeHeapSize());

    // Inicializa Nimble host stack
    ret = nimble_port_init();
    if (ret != ESP_OK) {
        ESP_LOG_E(TAG, "ERROR: Failed to initialize nimble stack, error code: %d ", ret);
        s_ble_state = BLE_STATE_STOPPED;
        ble_lifecycle_unlock();
        return ret;
    }

    // Inicializa la capa GAP del stack BLE y configura el nombre del dispositivo.
    char device_name[20] = {0};
    sprintf(device_name, "sfy%" PRIu64 "", s_device_id);
    rc = ble_gap_service_init(device_name);
    if (rc != 0) {
        ESP_LOG_E(TAG, "ERROR: Failed to initialize GAP service, error code: %d", rc);
        nimble_port_deinit();
        s_ble_state = BLE_STATE_STOPPED;
        ble_lifecycle_unlock();
        return ESP_FAIL;
    }

    // GATT server initialization
    // 1. Initialize GATT service
    // 2. Update NimBLE host GATT services counter
    // 3. Add GATT services to server
    rc = gatt_svc_init();
    if (rc != 0) {
        ESP_LOG_E(TAG, "ERROR: Failed to initialize GATT server, error code: %d", rc);
        nimble_port_deinit();
        s_ble_state = BLE_STATE_STOPPED;
        ble_lifecycle_unlock();
        return ESP_FAIL;
    }

    // configura todos los callbacks y los módulos base que necesita el host NimBLE antes de arrancar el stack BLE
    nimble_host_config_init();

    /* Start NimBLE host task thread and return */
    // Creo una task para que se ejecute el loop principal de BLE. Si lo ejecuto en app_main() bloquea. Termina si llamo a nimble_port_stop()
    BaseType_t task_rc = xTaskCreate(nimble_host_task, "NimBLE Host", 5*1024, NULL, 5, &s_nimble_host_task_handle);
    if (task_rc != pdPASS) {
        ESP_LOG_E(TAG, "ERROR: Failed to create NimBLE host task");
        nimble_port_deinit();
        s_ble_state = BLE_STATE_STOPPED;
        ble_lifecycle_unlock();
        return ESP_FAIL;
    }

    s_ble_started = true;
    s_ble_state = BLE_STATE_STARTED;
    ESP_LOG_I(TAG, "BLE transition: %s -> %s", ble_state_to_str(BLE_STATE_STARTING), ble_state_to_str(s_ble_state));
    ble_lifecycle_unlock();
    return ESP_OK;
}

esp_err_t ble_stop(void) {
    ble_lifecycle_lock();

    if (s_ble_state == BLE_STATE_STOPPED || !s_ble_started) {
        s_ble_state = BLE_STATE_STOPPED;
        ble_lifecycle_unlock();
        return ESP_OK;
    }

    if (s_ble_state == BLE_STATE_STOPPING || s_ble_state == BLE_STATE_STARTING) {
