static void ble_indicate_reset(ble_indicate_ctx_t *ctx) {
    ctx->tosend_buf = NULL;
    ctx->tosend_len = 0;
    ctx->tosend_offset = 0;
    ctx->tosend_chunk = 0;
    ctx->tosend_retries = 0;
    ctx->active = false;
    ctx->fragment = false;
    ctx->num_chunks = 0;
    ctx->chunk_len = 0;
    ctx->crc32 = 0;
}

