static void print_conn_info(struct ble_gap_conn_desc *desc, int verb) {

    if(verb > 1) {
        /* Local variables */
        char addr_str[18] = {0};

        /* Connection handle */
        ESP_LOGN(TAG, "Connection handle:\t%d", desc->conn_handle);

        /* Local ID address */
        format_addr(addr_str, desc->our_id_addr.val);
        ESP_LOGN(TAG, "Device id address:\ttype=%d, value=%s",
                desc->our_id_addr.type, addr_str);

        /* Peer ID address */
        format_addr(addr_str, desc->peer_id_addr.val);
        ESP_LOGN(TAG, "Peer id address:\ttype=%d, value=%s", desc->peer_id_addr.type,
             addr_str);
    }

    if(verb > 0) {
        /* Connection info */
        ESP_LOGN(TAG,
                "\tInfo: conn_itvl=%d, conn_latency=%d, supervision_timeout=%d, "
                "encrypted=%d, authenticated=%d, bonded=%d",
                desc->conn_itvl, desc->conn_latency, desc->supervision_timeout,
                desc->sec_state.encrypted, desc->sec_state.authenticated,
                desc->sec_state.bonded);
    }
}

/*
 * NimBLE applies an event-driven model to keep GAP service going
 * gap_event_handler is a callback function registered when calling
 * ble_gap_adv_start API and called when a GAP event arrives
 */
 static int gap_event_handler(struct ble_gap_event *event, void *arg) {
    /* Local variables */
    int rc = 0;
    struct ble_gap_conn_desc desc;

    switch (event->type) {

    /* Passive scan report: ADV externo recibido */
    case BLE_GAP_EVENT_DISC:
        ble_scanner_on_disc(&event->disc);
        return rc;

    /* Scan complete: si termina por timeout/error, se vuelve a iniciar */
    case BLE_GAP_EVENT_DISC_COMPLETE:
        ble_scanner_on_disc_complete(event->disc_complete.reason);
        return rc;

    /* Connect event */
    case BLE_GAP_EVENT_CONNECT:
        /* A new connection was established or a connection attempt failed. */
        ESP_LOGN(TAG, "BLE - Connection %s%s%s [status: %d]",
            event->connect.status == 0 ? LOG_COLOR_G : LOG_COLOR_R,
            event->connect.status == 0 ? "ESTABLISHED" : "FAILED",
            LOG_RESET_COLOR,
            event->connect.status);

        /* Connection succeeded */
        if (event->connect.status == 0) {
            active_conn_handle = event->connect.conn_handle;
            /* Check connection handle */
            // get connection descriptor
            rc = ble_gap_conn_find(event->connect.conn_handle, &desc);
            if (rc != 0) {
                ESP_LOG_E(TAG,"ERROR: Failed to find connection by handle [rc: %d]",rc);
                return rc;
            }

            /* Print connection info */
            print_conn_info(&desc, getVerb());

            /* Try to update connection parameters */
            // Estabiliza la conexion y optimiza consumo
            struct ble_gap_upd_params params = {.itvl_min = desc.conn_itvl,
                                                .itvl_max = desc.conn_itvl,
                                                .latency = 3,
                                                .supervision_timeout =
                                                    desc.supervision_timeout};
            rc = ble_gap_update_params(event->connect.conn_handle, &params);
            if (rc != 0) {
                ESP_LOG_E(TAG,"ERROR: Failed to update connection parameters [rc: %d]",rc);
                return rc;
            }
        }
        /* Connection failed, restart advertising */
        else {
            start_advertising();
        }
        return rc;

    /* Disconnect event */
    case BLE_GAP_EVENT_DISCONNECT:
        /* A connection was terminated, print connection descriptor */
        ESP_LOGN(TAG, "BLE - %sDisconnected%s from peer [reason: %d]", LOG_COLOR_R, LOG_RESET_COLOR,
                 event->disconnect.reason);
        active_conn_handle = BLE_HS_CONN_HANDLE_NONE;

        if (ble_get_app_link() == APP_LINK_DISABLED) {
            return rc;
        }

        /* Restart advertising */
        start_advertising();
        return rc;

    /* Connection parameters update event */
    case BLE_GAP_EVENT_CONN_UPDATE:
        /* The central has updated the connection parameters. */
        ESP_LOGN(TAG, "BLE - Connection UPDATED [status: %d]",
                 event->conn_update.status);

        /* Print connection descriptor */
        rc = ble_gap_conn_find(event->conn_update.conn_handle, &desc);
        if (rc != 0) {
            ESP_LOGE(TAG, "failed to find connection by handle, error code: %d",
                    rc);
            return rc;
        }
        print_conn_info(&desc, 1);

        return rc;

    /* Advertising complete event */
    // Puede pasar si el adv termino por timeout o error. Lo vuelve a iniciar
    case BLE_GAP_EVENT_ADV_COMPLETE:
        if (ble_get_app_link() == APP_LINK_DISABLED) {
            return rc;
        }
        /* Advertising completed, restart advertising */
        ESP_LOGN(TAG, "BLE - Advertising COMPLETED [reason: %d]. Restarting...",
                 event->adv_complete.reason);
        start_advertising();
        return rc;

    /* Notification sent event */
    case BLE_GAP_EVENT_NOTIFY_TX:
        ESP_LOGN(TAG,
                "BLE -\t[Event] %s: conn_handle=%d attr_handle=%d "
                "status=%d",
                event->notify_tx.indication ? "INDICATE" : "NOTIFY",
                event->notify_tx.conn_handle,
                event->notify_tx.attr_handle,
                event->notify_tx.status);

        if (event->notify_tx.indication) {
            ble_indicate_handler(event->notify_tx.attr_handle, event->notify_tx.status);
        }

        return rc;

    /* Subscribe event */
    case BLE_GAP_EVENT_SUBSCRIBE:
        /* Print subscription info to log */
        ESP_LOGN(TAG,
                 "BLE -\t[Event] Subscribe: conn_handle=%d attr_handle=%d "
                 "reason=%d prevn=%d curn=%d previ=%d curi=%d",
                 event->subscribe.conn_handle, event->subscribe.attr_handle,
                 event->subscribe.reason, event->subscribe.prev_notify,
                 event->subscribe.cur_notify, event->subscribe.prev_indicate,
                 event->subscribe.cur_indicate);

        /* GATT subscribe event callback */
        gatt_svr_subscribe_cb(event);
        return rc;

    /* MTU update event */
    case BLE_GAP_EVENT_MTU:
        /* Print MTU update info to log */
        ESP_LOGN(TAG, "BLE -\t[Event] MTU update: conn_handle=%d cid=%d mtu=%d",
                 event->mtu.conn_handle, event->mtu.channel_id,
                 event->mtu.value);
        return rc;
    }

    return rc;
}

