static ble_command_cb_t command_cb = NULL;
static ble_process_cloud_command_cb_t cloudCommand_cb = NULL;

esp_err_t comm_execute(uint16_t cmd, uint64_t value, char* buffer) {
    if (command_cb != NULL) {
        return command_cb(cmd, value, buffer);
    }
    return ESP_ERR_NOT_SUPPORTED;
