#include "security.h"
#include "esp_efuse.h"
#include "esp_efuse_table.h"
#include "esp_log.h"

bool is_secure_mode_enabled()
{
    // Verifica si Secure Boot ya está activado
    if (esp_efuse_read_field_bit(ESP_EFUSE_ABS_DONE_1)) {
        ESP_LOGI("SECURITY", "Secure Boot activado.");
        return true;
    }

    // Verifica si el UART ya está bloqueado
    if (esp_efuse_read_field_bit(ESP_EFUSE_UART_DOWNLOAD_DIS)) {
        ESP_LOGI("SECURITY", "El acceso por UART ya está bloqueado.");
        return true;
    }

    return false; // Si ninguno de los anteriores está activado, aún es posible quemar eFuses
}

bool burn_security_efuses()
{
    if (!is_secure_mode_enabled()) { // Solo quemar si aún está abierto el acceso
        ESP_LOGI("EFUSE", "Quemando eFuses para bloquear acceso por UART...");
        esp_efuse_write_field_bit(ESP_EFUSE_DISABLE_DL_ENCRYPT);
        esp_efuse_write_field_bit(ESP_EFUSE_DISABLE_DL_DECRYPT);
        esp_efuse_write_field_bit(ESP_EFUSE_DISABLE_DL_CACHE);
        esp_efuse_write_field_bit(ESP_EFUSE_UART_DOWNLOAD_DIS);
        ESP_LOGI("EFUSE", "eFuses quemados correctamente.");
        return true;
    } else {
        ESP_LOGI("SECURITY", "El dispositivo ya está seguro, no se quemarán eFuses.");
    }
    return false;
}

