esp_err_t ble_set_app_link(app_link_t value)
{
    if (value != APP_LINK_DISABLED && value != APP_LINK_ADV_DATA_LINK && value != APP_LINK_ADV_LINK && value != APP_LINK_LINK) {
        ESP_LOG_W(TAG, "BLE - PARAMS: invalid APP_LINK value %d", (int)value);
        return ESP_ERR_INVALID_ARG;
    }

    ble_lifecycle_lock();

    app_link_t previous = app_link;
    app_link = value;

    ESP_LOG_I(TAG,
              "BLE app_link transition: %s(%d) -> %s(%d)",
              app_link_to_str(previous),
              (int)previous,
              app_link_to_str(app_link),
              (int)app_link);

    if (previous == app_link) {
        ESP_LOG_I(TAG, "BLE app_link unchanged, no-op");
        ble_lifecycle_unlock();
        return ESP_OK;
    }

    if (app_link == APP_LINK_DISABLED) {
        esp_err_t err = ble_stop();
        ESP_LOG_I(TAG, "BLE app_link apply result: ble_stop rc=%d", (int)err);
        ble_lifecycle_unlock();
        return err;
    }

    if (previous != APP_LINK_DISABLED) {
        ble_gap_update_adv_payload();
        ESP_LOG_I(TAG, "BLE app_link apply result: ADV payload updated in-place");
        ble_lifecycle_unlock();
        return ESP_OK;
    }

    esp_err_t err = ble_start();
    ESP_LOG_I(TAG, "BLE app_link apply result: ble_start rc=%d", (int)err);
    ble_lifecycle_unlock();
    return err;
}

