 static void start_advertising(void) {
     int rc = 0;
     adv_profile_t profile = get_adv_profile();
     const char *name;
     struct ble_hs_adv_fields adv_fields;
     struct ble_hs_adv_fields rsp_fields;
     struct ble_gap_adv_params adv_params;
 
     /* Actualizar mfg_data solo en modo ADV+DATA+LINK */
     if (profile.include_mfg_data) {
         update_mfg_from_ram();
     }
 
     memset(&adv_fields, 0, sizeof(adv_fields));
     memset(&rsp_fields, 0, sizeof(rsp_fields));
     memset(&adv_params, 0, sizeof(adv_params));
 
     /* Flags: discoverable general, solo BLE (no BR/EDR) */
     adv_fields.flags = BLE_HS_ADV_F_DISC_GEN | BLE_HS_ADV_F_BREDR_UNSUP;
 
     /* Manufacturer data solo para APP_LINK_ADV_DATA_LINK */
     if (profile.include_mfg_data && mfg_len > 0) {
         adv_fields.mfg_data = mfg_buf;
         adv_fields.mfg_data_len = mfg_len;
     }
 
     /* Nombre solo en scan response para no superar 31 bytes en el ADV principal */
     if (profile.include_scan_rsp_name) {
         name = ble_svc_gap_device_name();
         rsp_fields.name = (uint8_t *)name;
         rsp_fields.name_len = strlen(name);
         rsp_fields.name_is_complete = 1;
     }
 
     rc = ble_gap_adv_set_fields(&adv_fields);
     if (rc != 0) {
         ESP_LOG_E(TAG, "ERROR: Failed to set advertising data [rc: %d]", rc);
         return;
     }
 
     /* Nombre del dispositivo en scan response (hasta 31 bytes disponibles) */
     rc = ble_gap_adv_rsp_set_fields(&rsp_fields);
     if (rc != 0) {
         ESP_LOG_E(TAG, "ERROR: Failed to set scan response data [rc: %d]", rc);
         return;
     }
 
     /* Modo connectable y discoverable general */
     // Con esto el dispositivo no es solo un “beacon”, es un periférico con el que se puede abrir una conexión GATT.
     adv_params.conn_mode = BLE_GAP_CONN_MODE_UND;   // cualquier central puede conectarse
     adv_params.disc_mode = BLE_GAP_DISC_MODE_GEN;   // lo mismo que las flags
 
     /* Intervalo de advertising */
     // Cuanto más corto, más rápido te descubren pero más consumo.
     adv_params.itvl_min = BLE_GAP_ADV_ITVL_MS(profile.adv_itvl_min_ms);
     adv_params.itvl_max = BLE_GAP_ADV_ITVL_MS(profile.adv_itvl_max_ms);
 
     /* Start advertising */
     rc = ble_gap_adv_start(own_addr_type
                             , NULL              // no pasás peer address (es un advertising no dirigido).
                             , BLE_HS_FOREVER    // sin timeout; sigue anunciando hasta que pares o te conecten
                             , &adv_params
                             , gap_event_handler         // callback para: conexiones, desconexiones, reintentos, suscripciones, etc.
                             , NULL);
 
     if (rc != 0) {
         ESP_LOG_E(TAG, "ERROR: Failed to start advertising [rc: %d]", rc);
         return;
     }
     ESP_LOG_I(TAG, "ADV profile=%s interval=%u-%u ms", profile.label, profile.adv_itvl_min_ms, profile.adv_itvl_max_ms);
     ESP_LOG_I(TAG, "ADV started successfully (fh: %d)", xPortGetFreeHeapSize());
 }
 
 static void print_conn_info(struct ble_gap_conn_desc *desc, int verb) {
     
     if(verb > 1) {
         /* Local variables */
         char addr_str[18] = {0};
 
         /* Connection handle */
         ESP_LOGN(TAG, "Connection handle:\t%d", desc->conn_handle);
 
         /* Local ID address */
         format_addr(addr_str, desc->our_id_addr.val);
         ESP_LOGN(TAG, "Device id address:\ttype=%d, value=%s",
                 desc->our_id_addr.type, addr_str);
 
         /* Peer ID address */
         format_addr(addr_str, desc->peer_id_addr.val);
         ESP_LOGN(TAG, "Peer id address:\ttype=%d, value=%s", desc->peer_id_addr.type,
              addr_str);
     }
 
     if(verb > 0) {
         /* Connection info */
         ESP_LOGN(TAG,
                 "\tInfo: conn_itvl=%d, conn_latency=%d, supervision_timeout=%d, "
                 "encrypted=%d, authenticated=%d, bonded=%d",
                 desc->conn_itvl, desc->conn_latency, desc->supervision_timeout,
                 desc->sec_state.encrypted, desc->sec_state.authenticated,
                 desc->sec_state.bonded);
     }
 }
 
 /*
  * NimBLE applies an event-driven model to keep GAP service going
  * gap_event_handler is a callback function registered when calling
  * ble_gap_adv_start API and called when a GAP event arrives
  */
  static int gap_event_handler(struct ble_gap_event *event, void *arg) {
     /* Local variables */
     int rc = 0;
     struct ble_gap_conn_desc desc;
 
     switch (event->type) {
 
