 static uint16_t ble_tracked_cmd_for_ctx(const ble_indicate_ctx_t *ctx)
 {
     if (ctx == &g_metadataRead) {
         return CMD_METADATA_READ;
     }
     if (ctx == &g_diagnosisRead) {
         return CMD_CONNECTIVITY_READ;
     }
     if (ctx == &g_paramResponse) {
         return CMD_PARAMS_READ;
     }
     return CMD_UNKNOWN;
 }
 
 static bool ble_is_tracked_read_cmd(uint16_t cmd)
 {
     return cmd == CMD_METADATA_READ ||
            cmd == CMD_CONNECTIVITY_READ ||
            cmd == CMD_PARAMS_READ;
 }
 
 static void ble_notify_tracked_cmd_status(uint16_t cmd, uint8_t status_code)
 {
     if (!ble_is_tracked_read_cmd(cmd)) {
         return;
     }
 
     esp_err_t err = ble_notify_send_dataStatus(cmd, status_code);
     if (err != ESP_OK) {
         ESP_LOG_W(TAG, "BLE - cmd 0x%04X status notify skipped [err: %d, status: 0x%02X]", cmd, err, status_code);
     }
 }
 
 static void ble_notify_tracked_ctx_status(const ble_indicate_ctx_t *ctx, uint8_t status_code)
 {
     uint16_t cmd = ble_tracked_cmd_for_ctx(ctx);
     if (cmd != CMD_UNKNOWN) {
         ble_notify_tracked_cmd_status(cmd, status_code);
     }
 }
 
 esp_err_t ble_notify_send_logControl(const uint8_t *data, size_t len)
 {
     if (!data || len == 0) {
         return ESP_ERR_INVALID_ARG;
     }
 
     if (!g_logControl.enabled ||
         g_logControl.conn_handle == BLE_HS_CONN_HANDLE_NONE ||
         g_logControl.attr_handle == 0) {
         return ESP_ERR_INVALID_STATE;
     }
 
     struct os_mbuf *om = ble_hs_mbuf_from_flat(data, len);
     if (!om) {
         ESP_LOG_E(TAG, "ERROR: logControl notify (%d) mbuf alloc failed", g_logControl.attr_handle);
         return ESP_ERR_NO_MEM;
     }
 
     int rc = ble_gatts_notify_custom(g_logControl.conn_handle, g_logControl.attr_handle, om);
     if (rc != 0) {
         ESP_LOG_E(TAG, "ERROR: logControl notify (%d) failed [rc: %d]", g_logControl.attr_handle, rc);
         return ESP_FAIL;
     }
 
     return ESP_OK;
 }
 
 static void ble_command_process(uint16_t cmd, uint64_t value, char* buffer) {
     ESP_LOGN(TAG, "BLE - commG: CMD-0x%04X received", cmd);
 
     esp_err_t err = comm_execute(cmd, value, buffer);
     if (err != ESP_OK) {
         ESP_LOG_E(TAG, "BLE - commG: CMD-0x%04X failed [err: %d]",cmd, err);
     }
     ble_notify_send_commResponse(cmd, err);
 }
 
