+static ble_secure_session_t s_session = {
+    .authenticated = false,
+    .handshake_done = false,
+    .conn_handle = BLE_HS_CONN_HANDLE_NONE,
+    .device_nonce = {0},
+    .app_nonce = {0},
+    .session_key = {0},
+    .rx_ctr_last = 0,
+    .tx_ctr_next = 1,
+};
+
+static const uint8_t s_ble_global_key[BLE_SECURE_KEY_LEN] = {
+    0x91, 0x27, 0x5A, 0x13, 0xC4, 0x6E, 0x22, 0xB8,
+    0x4D, 0xF0, 0x39, 0x7C, 0x11, 0xA5, 0xDE, 0x63,
+    0x88, 0x1F, 0xB4, 0x52, 0xE9, 0x0C, 0x73, 0xD6,
+    0x2A, 0x95, 0x48, 0xBC, 0x67, 0x10, 0xFE, 0x34,
+};
+
+static void store_u32_be(uint8_t *dst, uint32_t value)
+{
+    dst[0] = (uint8_t)((value >> 24) & 0xFF);
+    dst[1] = (uint8_t)((value >> 16) & 0xFF);
+    dst[2] = (uint8_t)((value >> 8) & 0xFF);
+    dst[3] = (uint8_t)(value & 0xFF);
+}
+
+static uint32_t load_u32_be(const uint8_t *src)
+{
+    return ((uint32_t)src[0] << 24) |
+           ((uint32_t)src[1] << 16) |
+           ((uint32_t)src[2] << 8) |
+           (uint32_t)src[3];
+}
+
+static void store_u16_be(uint8_t *dst, uint16_t value)
+{
+    dst[0] = (uint8_t)((value >> 8) & 0xFF);
+    dst[1] = (uint8_t)(value & 0xFF);
+}
+
+static uint16_t load_u16_be(const uint8_t *src)
+{
+    return (uint16_t)(((uint16_t)src[0] << 8) | src[1]);
+}
+
+static esp_err_t hmac_sha256_trunc16(const uint8_t *input,
+                                     size_t input_len,
+                                     uint8_t out_mac[BLE_SECURE_TAG_LEN])
+{
+    const mbedtls_md_info_t *md_info = mbedtls_md_info_from_type(MBEDTLS_MD_SHA256);
+    if (!md_info) {
+        return ESP_FAIL;
+    }
+
+    uint8_t full_mac[32] = {0};
+    int rc = mbedtls_md_hmac(md_info,
+                             s_ble_global_key,
+                             sizeof(s_ble_global_key),
+                             input,
+                             input_len,
+                             full_mac);
+    if (rc != 0) {
+        return ESP_FAIL;
+    }
+
+    memcpy(out_mac, full_mac, BLE_SECURE_TAG_LEN);
+    return ESP_OK;
+}
+
+static esp_err_t derive_session_key(uint8_t out_key[BLE_SECURE_KEY_LEN])
+{
+    uint8_t material[BLE_SECURE_KEY_LEN + (2 * BLE_SECURE_NONCE_LEN)] = {0};
+    memcpy(material, s_ble_global_key, BLE_SECURE_KEY_LEN);
+    memcpy(material + BLE_SECURE_KEY_LEN, s_session.device_nonce, BLE_SECURE_NONCE_LEN);
+    memcpy(material + BLE_SECURE_KEY_LEN + BLE_SECURE_NONCE_LEN, s_session.app_nonce, BLE_SECURE_NONCE_LEN);
+
+    int rc = mbedtls_sha256(material, sizeof(material), out_key, 0);
+    return rc == 0 ? ESP_OK : ESP_FAIL;
+}
+
+void ble_secure_session_reset(void)
+{
+    memset(&s_session, 0, sizeof(s_session));
+    s_session.conn_handle = BLE_HS_CONN_HANDLE_NONE;
+    s_session.tx_ctr_next = 1;
+}
+
+void ble_secure_session_on_connect(uint16_t conn_handle)
+{
+    ble_secure_session_reset();
+    s_session.conn_handle = conn_handle;
+    esp_fill_random(s_session.device_nonce, BLE_SECURE_NONCE_LEN);
+}
+
+bool ble_secure_is_authenticated(void)
+{
+    return s_session.authenticated;
+}
+
+uint16_t ble_secure_conn_handle(void)
+{
+    return s_session.conn_handle;
+}
+
+int ble_secure_build_auth_challenge(uint8_t *out_buf, size_t out_len, size_t *written_len)
+{
+    if (!out_buf || out_len < (2 + BLE_SECURE_NONCE_LEN)) {
+        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
+    }
+
+    out_buf[0] = BLE_SECURE_PROTOCOL_VERSION;
+    out_buf[1] = 0xA0;
+    memcpy(out_buf + 2, s_session.device_nonce, BLE_SECURE_NONCE_LEN);
+    if (written_len) {
+        *written_len = 2 + BLE_SECURE_NONCE_LEN;
+    }
+    return 0;
+}
+
+esp_err_t ble_secure_handle_auth_write(const uint8_t *buf, size_t len)
+{
+    if (!buf || len != (2 + (2 * BLE_SECURE_NONCE_LEN) + BLE_SECURE_TAG_LEN)) {
+        ESP_LOG_E(TAG, "BLE secure auth: invalid len=%u", (unsigned)len);
+        return ESP_ERR_INVALID_SIZE;
+    }
+
+    if (buf[0] != BLE_SECURE_PROTOCOL_VERSION || buf[1] != SEC_TYPE_AUTH_SYNC_REQ) {
+        ESP_LOG_E(TAG, "BLE secure auth: invalid header");
+        return ESP_ERR_INVALID_ARG;
+    }
+
+    const uint8_t *app_nonce = buf + 2;
+    const uint8_t *device_nonce = buf + 2 + BLE_SECURE_NONCE_LEN;
+    const uint8_t *received_mac = buf + 2 + (2 * BLE_SECURE_NONCE_LEN);
+
+    if (memcmp(device_nonce, s_session.device_nonce, BLE_SECURE_NONCE_LEN) != 0) {
+        ESP_LOG_E(TAG, "BLE secure auth: device nonce mismatch");
+        return ESP_ERR_INVALID_STATE;
+    }
+
+    uint8_t expected_mac[BLE_SECURE_TAG_LEN] = {0};
+    esp_err_t err = hmac_sha256_trunc16(buf, 2 + (2 * BLE_SECURE_NONCE_LEN), expected_mac);
+    if (err != ESP_OK) {
+        return err;
+    }
+
+    if (memcmp(received_mac, expected_mac, BLE_SECURE_TAG_LEN) != 0) {
+        ESP_LOG_E(TAG, "BLE secure auth: mac mismatch");
+        return ESP_ERR_INVALID_CRC;
+    }
+
+    memcpy(s_session.app_nonce, app_nonce, BLE_SECURE_NONCE_LEN);
+    err = derive_session_key(s_session.session_key);
+    if (err != ESP_OK) {
+        return err;
+    }
+
+    s_session.authenticated = true;
+    s_session.handshake_done = true;
+    s_session.rx_ctr_last = 0;
+    s_session.tx_ctr_next = 1;
+    ESP_LOG_I(TAG, "BLE secure auth: session established");
+    return ESP_OK;
+}
+
+static esp_err_t secure_crypt(bool encrypt,
+                              secure_type_t type,
+                              uint8_t flags,
+                              uint32_t ctr,
+                              const uint8_t iv[BLE_SECURE_NONCE_LEN],
+                              const uint8_t *input,
+                              uint16_t input_len,
+                              uint8_t *output,
+                              uint8_t tag[BLE_SECURE_TAG_LEN])
+{
+    uint8_t aad[8] = {0};
+    aad[0] = BLE_SECURE_PROTOCOL_VERSION;
+    aad[1] = (uint8_t)type;
+    aad[2] = flags;
+    aad[3] = 0x00;
+    store_u32_be(aad + 4, ctr);
+
+    uint8_t pt_len_be[2] = {0};
+    store_u16_be(pt_len_be, input_len);
+
+    mbedtls_gcm_context ctx;
+    mbedtls_gcm_init(&ctx);
+    int rc = mbedtls_gcm_setkey(&ctx, MBEDTLS_CIPHER_ID_AES, s_session.session_key, BLE_SECURE_KEY_LEN * 8);
+    if (rc == 0) {
+        uint8_t aad_full[10] = {0};
+        memcpy(aad_full, aad, sizeof(aad));
+        memcpy(aad_full + sizeof(aad), pt_len_be, sizeof(pt_len_be));
+        if (encrypt) {
+            rc = mbedtls_gcm_crypt_and_tag(&ctx,
+                                           MBEDTLS_GCM_ENCRYPT,
+                                           input_len,
+                                           iv,
+                                           BLE_SECURE_NONCE_LEN,
+                                           aad_full,
+                                           sizeof(aad_full),
+                                           input,
+                                           output,
+                                           BLE_SECURE_TAG_LEN,
+                                           tag);
+        } else {
+            rc = mbedtls_gcm_auth_decrypt(&ctx,
+                                          input_len,
+                                          iv,
+                                          BLE_SECURE_NONCE_LEN,
+                                          aad_full,
+                                          sizeof(aad_full),
+                                          tag,
+                                          BLE_SECURE_TAG_LEN,
+                                          input,
+                                          output);
+        }
+    }
+    mbedtls_gcm_free(&ctx);
+    return rc == 0 ? ESP_OK : ESP_ERR_INVALID_CRC;
+}
+
+esp_err_t ble_secure_encode_message(secure_type_t type,
+                                    const uint8_t *payload,
+                                    size_t payload_len,
+                                    uint8_t **out_buf,
+                                    size_t *out_len)
+{
+    if (!out_buf || !out_len || !payload || payload_len == 0 || payload_len > UINT16_MAX) {
+        return ESP_ERR_INVALID_ARG;
+    }
+    if (!s_session.authenticated) {
+        return ESP_ERR_INVALID_STATE;
+    }
+
+    const size_t total_len = BLE_SECURE_FRAME_HEADER_LEN + payload_len + BLE_SECURE_TAG_LEN;
+    uint8_t *frame = (uint8_t *)malloc(total_len);
+    if (!frame) {
+        return ESP_ERR_NO_MEM;
+    }
+
+    uint8_t *p = frame;
+    p[0] = BLE_SECURE_PROTOCOL_VERSION;
+    p[1] = (uint8_t)type;
+    p[2] = 0x00;
+    p[3] = 0x00;
+    store_u32_be(p + 4, s_session.tx_ctr_next);
+    esp_fill_random(p + 8, BLE_SECURE_NONCE_LEN);
+    store_u16_be(p + 20, (uint16_t)payload_len);
+
+    esp_err_t err = secure_crypt(true,
+                                 type,
+                                 p[2],
+                                 s_session.tx_ctr_next,
+                                 p + 8,
+                                 payload,
+                                 (uint16_t)payload_len,
+                                 p + BLE_SECURE_FRAME_HEADER_LEN,
+                                 p + BLE_SECURE_FRAME_HEADER_LEN + payload_len);
+    if (err != ESP_OK) {
+        free(frame);
+        return err;
+    }
+
+    s_session.tx_ctr_next++;
+    *out_buf = frame;
+    *out_len = total_len;
+    return ESP_OK;
+}
+
+esp_err_t ble_secure_decode_message(const uint8_t *buf,
+                                    size_t len,
+                                    secure_type_t expected_type,
+                                    ble_secure_decoded_msg_t *out_msg)
+{
+    if (!buf || !out_msg || len < (BLE_SECURE_FRAME_HEADER_LEN + BLE_SECURE_TAG_LEN)) {
+        return ESP_ERR_INVALID_ARG;
+    }
+    if (!s_session.authenticated) {
+        return ESP_ERR_INVALID_STATE;
+    }
+
+    memset(out_msg, 0, sizeof(*out_msg));
+    if (buf[0] != BLE_SECURE_PROTOCOL_VERSION) {
+        return ESP_ERR_INVALID_ARG;
+    }
+
+    secure_type_t type = (secure_type_t)buf[1];
+    if (type != expected_type) {
+        return ESP_ERR_INVALID_ARG;
+    }
+
+    uint8_t flags = buf[2];
+    uint32_t ctr = load_u32_be(buf + 4);
+    uint16_t payload_len = load_u16_be(buf + 20);
+    const size_t expected_len = BLE_SECURE_FRAME_HEADER_LEN + payload_len + BLE_SECURE_TAG_LEN;
+    if (len != expected_len) {
+        return ESP_ERR_INVALID_SIZE;
+    }
+    if (ctr <= s_session.rx_ctr_last) {
+        return ESP_ERR_INVALID_STATE;
+    }
+
+    uint8_t *payload = (uint8_t *)malloc((size_t)payload_len + 1);
+    if (!payload) {
+        return ESP_ERR_NO_MEM;
+    }
+
+    esp_err_t err = secure_crypt(false,
+                                 type,
+                                 flags,
+                                 ctr,
+                                 buf + 8,
+                                 buf + BLE_SECURE_FRAME_HEADER_LEN,
+                                 payload_len,
+                                 payload,
+                                 (uint8_t *)(buf + BLE_SECURE_FRAME_HEADER_LEN + payload_len));
+    if (err != ESP_OK) {
+        free(payload);
+        return err;
+    }
+
+    payload[payload_len] = '\0';
+    s_session.rx_ctr_last = ctr;
+
+    out_msg->version = buf[0];
+    out_msg->type = type;
+    out_msg->flags = flags;
+    out_msg->ctr = ctr;
+    out_msg->payload = payload;
+    out_msg->payload_len = payload_len;
+    return ESP_OK;
+}
+
+void ble_secure_decoded_msg_free(ble_secure_decoded_msg_t *msg)
+{
+    if (!msg) {
+        return;
+    }
+    if (msg->payload) {
+        free(msg->payload);
+    }
+    memset(msg, 0, sizeof(*msg));
+}

