+
+static secure_type_t ble_secure_expected_type_for_attr(uint16_t attr_handle)
+{
+    if (attr_handle == commandGet_handle) {
+        return SEC_TYPE_COMMAND_GET_REQ;
+    }
+    if (attr_handle == commandData_handle) {
+        return SEC_TYPE_COMMAND_DATA_REQ;
+    }
+    if (attr_handle == timeSync_handle) {
+        return SEC_TYPE_TIME_SYNC_REQ;
+    }
+    if (attr_handle == commGet_handle) {
+        return SEC_TYPE_COMM_GET_REQ;
+    }
+    if (attr_handle == paramGet_handle) {
+        return SEC_TYPE_PARAM_GET_REQ;
+    }
+    return SEC_TYPE_AUTH_SYNC_RSP;
+}
+
+static secure_type_t ble_secure_indicate_type_for_ctx(const ble_indicate_ctx_t *ctx)
+{
+    if (ctx == &g_metadataRead) {
+        return SEC_TYPE_METADATA_RSP;
+    }
+    if (ctx == &g_historySend) {
+        return SEC_TYPE_HISTORY_RSP;
+    }
+    if (ctx == &g_diagnosisRead) {
+        return SEC_TYPE_DIAGNOSIS_RSP;
+    }
+    if (ctx == &g_paramResponse) {
+        return SEC_TYPE_PARAM_RESPONSE_RSP;
+    }
+    return SEC_TYPE_AUTH_SYNC_RSP;
+}
+
+static int ble_secure_disconnect_and_return(int rc, const char *reason)
+{
+    ESP_LOG_E(TAG, "BLE secure failure: %s", reason ? reason : "unknown");
+    ble_secure_disconnect_active();
+    rcvMsg_reset();
+    return rc;
+}
