/*
 * NimBLE applies an event-driven model to keep GAP service going
 * gap_event_handler is a callback function registered when calling
 * ble_gap_adv_start API and called when a GAP event arrives
 */
 static int gap_event_handler(struct ble_gap_event *event, void *arg) {
    /* Local variables */
    int rc = 0;
    struct ble_gap_conn_desc desc;

    switch (event->type) {

    /* Passive scan report: ADV externo recibido */
    case BLE_GAP_EVENT_DISC:
        ble_scanner_on_disc(&event->disc);
        return rc;

    /* Scan complete: si termina por timeout/error, se vuelve a iniciar */
    case BLE_GAP_EVENT_DISC_COMPLETE:
        ble_scanner_on_disc_complete(event->disc_complete.reason);
        return rc;

    /* Connect event */
    case BLE_GAP_EVENT_CONNECT:
        /* A new connection was established or a connection attempt failed. */
        ESP_LOGN(TAG, "BLE - Connection %s%s%s [status: %d]",
            event->connect.status == 0 ? LOG_COLOR_G : LOG_COLOR_R,
            event->connect.status == 0 ? "ESTABLISHED" : "FAILED",
            LOG_RESET_COLOR,
            event->connect.status);

        /* Connection succeeded */
        if (event->connect.status == 0) {
            active_conn_handle = event->connect.conn_handle;
            ble_secure_session_on_connect(active_conn_handle);
            /* Check connection handle */
            // get connection descriptor
            rc = ble_gap_conn_find(event->connect.conn_handle, &desc);
            if (rc != 0) {
                ESP_LOG_E(TAG,"ERROR: Failed to find connection by handle [rc: %d]",rc);
                return rc;
            }

            /* Print connection info */
            print_conn_info(&desc, getVerb());

            /* Try to update connection parameters */
            // Estabiliza la conexion y optimiza consumo
            struct ble_gap_upd_params params = {.itvl_min = desc.conn_itvl,
                                                .itvl_max = desc.conn_itvl,
                                                .latency = 3,
                                                .supervision_timeout =
                                                    desc.supervision_timeout};
            rc = ble_gap_update_params(event->connect.conn_handle, &params);
            if (rc != 0) {
                ESP_LOG_E(TAG,"ERROR: Failed to update connection parameters [rc: %d]",rc);
                return rc;
            }
        }
        /* Connection failed, restart advertising */
        else {
            start_advertising();
        }
        return rc;

    /* Disconnect event */
    case BLE_GAP_EVENT_DISCONNECT:
        /* A connection was terminated, print connection descriptor */
        ESP_LOGN(TAG, "BLE - %sDisconnected%s from peer [reason: %d]", LOG_COLOR_R, LOG_RESET_COLOR,
                 event->disconnect.reason);
        active_conn_handle = BLE_HS_CONN_HANDLE_NONE;
        ble_secure_session_reset();
        rcvMsg_reset();

        if (ble_get_app_link() == APP_LINK_DISABLED) {
            return rc;
        }

        /* Restart advertising */
        start_advertising();
        return rc;

    /* Connection parameters update event */
    case BLE_GAP_EVENT_CONN_UPDATE:
        /* The central has updated the connection parameters. */
        ESP_LOGN(TAG, "BLE - Connection UPDATED [status: %d]",
                 event->conn_update.status);

        /* Print connection descriptor */
        rc = ble_gap_conn_find(event->conn_update.conn_handle, &desc);
