static int commGet_access_cb(uint16_t conn_handle, uint16_t attr_handle, struct ble_gatt_access_ctxt *ctxt, void *arg)
{
    (void)conn_handle;
    (void)arg;
    if (attr_handle != commGet_handle) {
        ESP_LOG_E(TAG, "BLE - ERROR: unexpected attr_handle = %d", attr_handle);
        return BLE_ATT_ERR_UNLIKELY;
    }

    if (ctxt->op != BLE_GATT_ACCESS_OP_WRITE_CHR) {
        ESP_LOG_E(TAG, "BLE - ERROR: unsupported op = %d", ctxt->op);
        return BLE_ATT_ERR_UNLIKELY;
    }

    if (!ble_secure_is_authenticated()) {
        return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "commGet before auth");
    }

    uint16_t incoming_len = OS_MBUF_PKTLEN(ctxt->om);
    if (incoming_len == 0) {
        ESP_LOG_E(TAG, "BLE - commGet ERROR: empty payload");
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    uint8_t *chunk = (uint8_t *)malloc(incoming_len);
    if (!chunk) {
        ESP_LOG_E(TAG, "BLE - commGet ERROR: malloc chunk failed");
        return BLE_ATT_ERR_UNLIKELY;
    }

    int rc = ble_hs_mbuf_to_flat(ctxt->om, chunk, incoming_len, &incoming_len);
    if (rc != 0) {
        ESP_LOG_E(TAG, "BLE - commGet ERROR: mbuf_to_flat [rc: %d]", rc);
        free(chunk);
        return BLE_ATT_ERR_UNLIKELY;
    }

    bool is_complete = false;
    rc = rcvMsg_feed(chunk, incoming_len, &is_complete);

    if (is_complete) {
        ble_secure_decoded_msg_t msg = {};
        esp_err_t err = ble_secure_decode_message(rcvMsg_buffer(), rcvMsg_len(), SEC_TYPE_COMM_GET_REQ, &msg);
        if (err != ESP_OK) {
            free(chunk);
            rcvMsg_reset();
            ble_secure_decoded_msg_free(&msg);
            return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "commGet secure decode failed");
        }
        ble_process_cloud_command((char*)msg.payload, msg.payload_len);
        ble_secure_decoded_msg_free(&msg);
        rcvMsg_reset();
    }

    free(chunk);
    if (rc != 0) {
        return rc;
    }

    return 0;
}

