int rcvMsg_feed(const uint8_t *chunk, size_t incoming_len, bool *is_complete)
{
    uint32_t seq = 0;
    uint32_t n = 0;
    size_t total_len = 0;
    size_t payload_offset = 0;
    uint32_t expected_crc32 = 0;
    char flag = 0;

    if (parse_chunk_header(chunk, incoming_len,
                           &seq, &n, &total_len, &expected_crc32, &flag,
                           &payload_offset) != 0) {
        ESP_LOG_E(TAG, "BLE - ERROR: invalid chunk header");
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    size_t payload_len = incoming_len - payload_offset;
    const uint8_t *payload = chunk + payload_offset;

    if (!g_rcv.receiving) {
        bool valid_first = (seq == 0) && (flag == 'S' || (flag == 'E' && n == 1));
        if (!valid_first) {
            ESP_LOG_E(TAG, "BLE - ERROR: first chunk must be SEQ=0 with F=S or F=E (if N=1)");
            rcvMsg_reset();
            return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
        }
        if (total_len > SFY_CONFIG_MAX_SIZE) {
            ESP_LOG_E(TAG, "BLE - ERROR: LEN %u exceeds SFY_CONFIG_MAX_SIZE", (unsigned)total_len);
            rcvMsg_reset();
            return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
        }
        g_rcv.total_chunks = n;
        g_rcv.total_len = total_len;
        g_rcv.expected_crc32 = expected_crc32;
        g_rcv.expected_seq = 1;
        g_rcv.receiving = true;
    } else {
        if (seq != g_rcv.expected_seq) {
            ESP_LOG_E(TAG, "BLE - ERROR: out-of-order chunk: expected SEQ=%u got %u",
                     (unsigned)g_rcv.expected_seq, (unsigned)seq);
            rcvMsg_reset();
            return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
        }
        g_rcv.expected_seq++;
    }

    size_t needed_size = g_rcv.offset + payload_len;
    if (needed_size > g_rcv.total_len) {
        ESP_LOG_E(TAG, "BLE - ERROR: payload overflow: offset=%u + payload=%u > LEN=%u",
                 (unsigned)g_rcv.offset, (unsigned)payload_len, (unsigned)g_rcv.total_len);
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    if (realloc_buffer(needed_size + 1) < 0) {
