                 (unsigned)(seq + 1), (unsigned)g_rcv.total_chunks, (unsigned)payload_len, (unsigned)g_rcv.offset);
        if (is_complete) {
            *is_complete = false;
        }
        return 0;
    }

    if (g_rcv.offset != g_rcv.total_len) {
        ESP_LOG_E(TAG, "BLE - ERROR: F=E but length mismatch: have %u expected %u",
                 (unsigned)g_rcv.offset, (unsigned)g_rcv.total_len);
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    uint32_t computed_crc = esp_rom_crc32_le(0xFFFFFFFFu, g_rcv.buffer, g_rcv.offset);
    if (computed_crc != g_rcv.expected_crc32) {
