                 (unsigned long)computed_crc, (unsigned long)g_rcv.expected_crc32);
        rcvMsg_reset();
        return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
    }

    g_rcv.buffer[g_rcv.offset] = '\0';
    ESP_LOGN(TAG, "BLE - received %sCOMPLETED%s | total = %u bytes | chunks = %u",
             LOG_COLOR_G, LOG_RESET_COLOR, (unsigned)g_rcv.offset, (unsigned)g_rcv.total_chunks);

    if (is_complete) {
        *is_complete = true;
    }
    return 0;
