{
    char* ret = nullptr;

    if (buffer == NULL)
    {
        return nullptr;
    }

    cJSON *json_parse = cJSON_Parse(buffer);
    if (json_parse == NULL)
    {
        return nullptr;
    }

    cJSON *_tipo = cJSON_GetObjectItem(json_parse,JSON_ITEM);

    if (_tipo != NULL)
    {
        if (cJSON_IsString(_tipo) && (_tipo->valuestring != NULL))
        {
            ret = new char[40];
            if (ret == nullptr)
            {
                return ret;
            }
            strcpy(ret,_tipo->valuestring );
        }
    }

    cJSON_Delete(json_parse);
    return ret;
