bool Time_sync::getLocalTimestapHL(uint16_t* reg_hi, uint16_t* reg_lo, int tz_offset_minutes)
{
    if (!isSynchronized()|| reg_hi==NULL || reg_lo==NULL) return false;

    // 1) Tomamos epoch UTC actual desde tu librería
    epoch_t e = get_epoch_time_ms(esp_log_timestamp()); // e.sec es UTC en segundos
    // 2) Lo llevamos a hora local aplicando offset (minutos)
    int64_t local_sec = (int64_t)e.sec + (int64_t)tz_offset_minutes * 60;

    // 3) Cast a 32 bits (protocolo pide 32-bit hex)
    uint32_t local_epoch32 = (uint32_t)local_sec;

    // 4) Partimos en dos registros de 16 bits
    *reg_hi = (uint16_t)((local_epoch32 >> 16) & 0xFFFF); // TIMESTAMP_HI  (registro 103)
    *reg_lo = (uint16_t)( local_epoch32        & 0xFFFF); // TIMESTAMP_LO  (registro 104)

    return true;
}

