 /*
  *  GATT server initialization
  *      1. Initialize GATT service
  *      2. Update NimBLE host GATT services counter
  *      3. Add GATT services to server
  */
 int gatt_svc_init(void) {
     /* Local variables */
     int rc;
 
     g_indicate_ctx_count = 0;
     g_notify_ctx_count = 0;
     memset(g_indicate_ctxs, 0, sizeof(g_indicate_ctxs));
     memset(g_notify_ctxs, 0, sizeof(g_notify_ctxs));
 
     // Inicializo GATT service
     ble_svc_gatt_init();
 
     // Cuenta y reserva memoria para los servicios, caracteristicas y descriptores del servidor
     rc = ble_gatts_count_cfg(gatt_services);
     if (rc != 0) {
         return rc;
     }
 
     // Agrega servicios al servidor
     rc = ble_gatts_add_svcs(gatt_services);
     if (rc != 0) {
         return rc;
     }
 
     if (!s_gatt_runtime_inited) {
         ble_npl_event_init(&g_historySend.send_event,
                        ble_indicate_send_event_cb,
                        &g_historySend);
     }
     g_indicate_ctxs[0] = &g_historySend;
     g_indicate_ctx_count++;
 
     if (!s_gatt_runtime_inited) {
         ble_npl_event_init(&g_paramResponse.send_event,
                        ble_indicate_send_event_cb,
                        &g_paramResponse);
     }
     g_indicate_ctxs[1] = &g_paramResponse;
     g_indicate_ctx_count++;
 
     if (!s_gatt_runtime_inited) {
         ble_npl_event_init(&g_metadataRead.send_event,
                        ble_indicate_send_event_cb,
                        &g_metadataRead);
     }
     g_indicate_ctxs[2] = &g_metadataRead;
     g_indicate_ctx_count++;
 
     if (!s_gatt_runtime_inited) {
         ble_npl_event_init(&g_diagnosisRead.send_event,
                        ble_indicate_send_event_cb,
                        &g_diagnosisRead);
     }
     g_indicate_ctxs[3] = &g_diagnosisRead;
     g_indicate_ctx_count++;
 
     if (!s_gatt_runtime_inited) {
         ble_npl_callout_init(&g_logSend.callout,
                              nimble_port_get_dflt_eventq(),
                              ble_notify_tick_cb,
                              &g_logSend);
         ble_npl_callout_init(&g_logTerminal.callout,
                              nimble_port_get_dflt_eventq(),
                              ble_notify_tick_cb,
                              &g_logTerminal);
         s_gatt_runtime_inited = true;
     }
     g_notify_ctxs[0] = &g_logSend;
     g_notify_ctx_count++;
 
     g_notify_ctxs[1] = &g_commResponse;
     g_notify_ctx_count++;
 
     g_notify_ctxs[2] = &g_logControl;
     g_notify_ctx_count++;
 
     g_notify_ctxs[3] = &g_dataStatus;
     g_notify_ctx_count++;
 
     g_notify_ctxs[4] = &g_logTerminal;
     g_notify_ctx_count++;
 
     return 0;
 }
 
 // Se setea en nimble_host_config_init. Solo imprime cosas
 void gatt_svr_register_cb(struct ble_gatt_register_ctxt *ctxt, void *arg) {
     /* Local variables */
     char buf[BLE_UUID_STR_LEN];
 
     /* Handle GATT attributes register events */
     switch (ctxt->op) {
 
     /* Service register event */
     case BLE_GATT_REGISTER_OP_SVC:
         ESP_LOGD(TAG, "registered service %s with handle=%d",
                  ble_uuid_to_str(ctxt->svc.svc_def->uuid, buf),
                  ctxt->svc.handle);
         break;
 
     /* Characteristic register event */
     case BLE_GATT_REGISTER_OP_CHR:
         ESP_LOGD(TAG,
                  "registering characteristic %s with "
                  "def_handle=%d val_handle=%d",
                  ble_uuid_to_str(ctxt->chr.chr_def->uuid, buf),
                  ctxt->chr.def_handle, ctxt->chr.val_handle);
         break;
 
     /* Descriptor register event */
     case BLE_GATT_REGISTER_OP_DSC:
         ESP_LOGD(TAG, "registering descriptor %s with handle=%d",
                  ble_uuid_to_str(ctxt->dsc.dsc_def->uuid, buf),
                  ctxt->dsc.handle);
         break;
 
     /* Unknown event */
     default:
         assert(0);
         break;
     }
 }
 
 void gatt_svr_subscribe_cb(struct ble_gap_event *event) {
     /* Check connection handle */
     if (event->subscribe.conn_handle != BLE_HS_CONN_HANDLE_NONE) {
         if(getVerb() > 0) {
             ESP_LOGN(TAG, "BLE - Subscribe CB: conn_handle=%d attr_handle=%d",
                     event->subscribe.conn_handle, event->subscribe.attr_handle);
         }
     } else {
         ESP_LOGN(TAG, "BLE - Subscribe CB: subscribe by nimble stack (attr_handle=%d)",
                  event->subscribe.attr_handle);
     }
 
     /* Check attribute handle */
     // Suscripciones
     ble_indicate_ctx_t *indicate_ctx = get_indicate_ctx(event->subscribe.attr_handle);
     if (indicate_ctx) {
         indicate_ctx->conn_handle = event->subscribe.conn_handle;
         indicate_ctx->enabled = event->subscribe.cur_indicate;
 
         if (!indicate_ctx->enabled) {
             indicate_ctx->active = false;
             ble_indicate_abort(indicate_ctx);
             // TODO: Si hay una secuencia de datos pendiente, abortarla
         }
 
         ESP_LOGN(TAG, "BLE -\tINDICATE Subscription OK (attr=%d)",
                  (int)indicate_ctx->attr_handle);
     }
 
     ble_notify_ctx_t *notify_ctx = get_notify_ctx_by_handle(event->subscribe.attr_handle);
     if (notify_ctx) {
         notify_ctx->conn_handle = event->subscribe.conn_handle;
         notify_ctx->enabled = event->subscribe.cur_notify;
 
         if (notify_ctx == &g_logSend) {
             if (notify_ctx->enabled &&
                 notify_ctx->conn_handle != BLE_HS_CONN_HANDLE_NONE) {
                 notify_ctx->active = true;
                 ble_npl_callout_reset(&notify_ctx->callout,
                                       ble_npl_time_ms_to_ticks32(0));
             } else {
                 notify_ctx->active = false;
                 ble_npl_callout_stop(&notify_ctx->callout);
             }
         }
 
         if (notify_ctx == &g_logTerminal) {
             if (notify_ctx->enabled &&
                 notify_ctx->conn_handle != BLE_HS_CONN_HANDLE_NONE) {
                 ble_logTerminal_capture_enable();
                 notify_ctx->active = true;
                 ble_npl_callout_reset(&notify_ctx->callout,
                                       ble_npl_time_ms_to_ticks32(0));
             } else {
                 ble_logTerminal_capture_disable();
             }
         }
 
         if (!notify_ctx->enabled) {
             notify_ctx->active = false;
             if (notify_ctx->interval_ms > 0 && notify_ctx->next_msg_cb) {
                 ble_npl_callout_stop(&notify_ctx->callout);
             }
         }
 
         ESP_LOGN(TAG, "BLE -\tNOTIFY Subscription OK (attr=%d)",
                  (int)notify_ctx->attr_handle);
     }
 }
 
 // HELPERS ==============================================
 
 static ble_notify_ctx_t *get_notify_ctx_by_handle(uint16_t attr_handle)
 {
     for (size_t i = 0; i < g_notify_ctx_count; i++) {
         if (g_notify_ctxs[i] && g_notify_ctxs[i]->attr_handle == attr_handle) {
             return g_notify_ctxs[i];
         }
     }
     return NULL;
 }
 
 static secure_type_t ble_secure_indicate_type_for_ctx(const ble_indicate_ctx_t *ctx)
 {
     if (ctx == &g_metadataRead) {
         return SEC_TYPE_METADATA_RSP;
     }
     if (ctx == &g_historySend) {
         return SEC_TYPE_HISTORY_RSP;
     }
     if (ctx == &g_diagnosisRead) {
         return SEC_TYPE_DIAGNOSIS_RSP;
     }
     if (ctx == &g_paramResponse) {
         return SEC_TYPE_PARAM_RESPONSE_RSP;
     }
     return SEC_TYPE_AUTH_SYNC_RSP;
 }
 
 static int ble_secure_disconnect_and_return(int rc, const char *reason)
 {
     ESP_LOG_E(TAG, "BLE secure failure: %s", reason ? reason : "unknown");
     ble_secure_disconnect_active();
     rcvMsg_reset();
     return rc;
 }
 
 static void ble_notify_tick_cb(struct ble_npl_event *ev)
 {
     ble_notify_ctx_t *ctx = (ble_notify_ctx_t *)ble_npl_event_get_arg(ev);
     if (!ctx || !ctx->active || !ctx->enabled ||
         ctx->conn_handle == BLE_HS_CONN_HANDLE_NONE || !ctx->next_msg_cb) {
         return;
     }
 
     bool sent_any = false;
     uint8_t max_to_send = ctx->max_per_interval;
 
     while (max_to_send > 0) {
         max_to_send--;
         size_t len = 0;
         uint8_t *data = ctx->next_msg_cb(&len);
 
         if (!data || len == 0) {
             break;
         }
 
         struct os_mbuf *om = ble_hs_mbuf_from_flat(data, len);
         if (!om) {
             ESP_LOG_E(TAG, "ERROR: notify (%d) mbuf alloc failed", ctx->attr_handle);
             free(data);
             break;
         }
 
         int rc = ble_gatts_notify_custom(ctx->conn_handle, ctx->attr_handle, om);
         if (rc != 0) {
             ESP_LOG_E(TAG, "ERROR: notify (%d) failed [rc: %d]", ctx->attr_handle, rc);
             free(data);
             break;
         }
 
         free(data);
         sent_any = true;
     }
 
     if (sent_any) {
         ESP_LOG_I(TAG, "BLE - NOTIFY (%d) batch sent. Next send in %" PRIu32" ms", ctx->attr_handle, ctx->interval_ms);
     }
 
     ble_npl_callout_reset(&ctx->callout,
                           ble_npl_time_ms_to_ticks32(ctx->interval_ms));
 }
 
 static esp_err_t ble_notify_send_commResponse(uint16_t cmd, uint8_t err_code)
 {
     if (!g_commResponse.enabled ||
         g_commResponse.conn_handle == BLE_HS_CONN_HANDLE_NONE) {
         return ESP_ERR_INVALID_STATE;
     }
 
     uint8_t payload[3];
     payload[0] = (uint8_t)((cmd >> 8) & 0xFF);
     payload[1] = (uint8_t)(cmd & 0xFF);
     payload[2] = err_code;
 
     uint8_t *secure_payload = NULL;
     size_t secure_len = 0;
     esp_err_t err = ble_secure_encode_message(SEC_TYPE_COMMANDS_RSP, payload, sizeof(payload), &secure_payload, &secure_len);
     if (err != ESP_OK) {
         return err;
     }
 
     struct os_mbuf *om = ble_hs_mbuf_from_flat(secure_payload, secure_len);
     if (!om) {
         free(secure_payload);
         ESP_LOG_E(TAG, "ERROR: notify (%d) mbuf alloc failed", g_commResponse.attr_handle);
         return ESP_ERR_NO_MEM;
     }
 
     int rc = ble_gatts_notify_custom(g_commResponse.conn_handle, g_commResponse.attr_handle, om);
     free(secure_payload);
     if (rc != 0) {
         ESP_LOG_E(TAG, "ERROR: commResponse notify (%d) failed [rc: %d]", g_commResponse.attr_handle, rc);
         return ESP_FAIL;
     }
 
     return ESP_OK;
 }
 
 static esp_err_t ble_notify_send_dataStatus(uint16_t cmd, uint8_t err_code)
 {
     if (!g_dataStatus.enabled ||
         g_dataStatus.conn_handle == BLE_HS_CONN_HANDLE_NONE) {
         return ESP_ERR_INVALID_STATE;
     }
 
     uint8_t payload[3];
     payload[0] = (uint8_t)((cmd >> 8) & 0xFF);
     payload[1] = (uint8_t)(cmd & 0xFF);
     payload[2] = err_code;
 
     uint8_t *secure_payload = NULL;
     size_t secure_len = 0;
     esp_err_t err = ble_secure_encode_message(SEC_TYPE_DATA_STATUS_RSP, payload, sizeof(payload), &secure_payload, &secure_len);
     if (err != ESP_OK) {
         return err;
     }
 
     struct os_mbuf *om = ble_hs_mbuf_from_flat(secure_payload, secure_len);
     if (!om) {
         free(secure_payload);
         ESP_LOG_E(TAG, "ERROR: notify (%d) mbuf alloc failed", g_dataStatus.attr_handle);
         return ESP_ERR_NO_MEM;
     }
 
     int rc = ble_gatts_notify_custom(g_dataStatus.conn_handle, g_dataStatus.attr_handle, om);
     free(secure_payload);
     if (rc != 0) {
         ESP_LOG_E(TAG, "ERROR: dataStatus notify (%d) failed [rc: %d]", g_dataStatus.attr_handle, rc);
         return ESP_FAIL;
     }
 
     return ESP_OK;
 }
 
 static uint16_t ble_tracked_cmd_for_ctx(const ble_indicate_ctx_t *ctx)
 {
     if (ctx == &g_metadataRead) {
         return CMD_METADATA_READ;
     }
     if (ctx == &g_diagnosisRead) {
         return CMD_CONNECTIVITY_READ;
     }
     if (ctx == &g_paramResponse) {
         return CMD_PARAMS_READ;
     }
     return CMD_UNKNOWN;
 }
 
 static bool ble_is_tracked_read_cmd(uint16_t cmd)
 {
     return cmd == CMD_METADATA_READ ||
            cmd == CMD_CONNECTIVITY_READ ||
            cmd == CMD_PARAMS_READ;
 }
 
 static void ble_notify_tracked_cmd_status(uint16_t cmd, uint8_t status_code)
 {
     if (!ble_is_tracked_read_cmd(cmd)) {
         return;
     }
 
     esp_err_t err = ble_notify_send_dataStatus(cmd, status_code);
     if (err != ESP_OK) {
         ESP_LOG_W(TAG, "BLE - cmd 0x%04X status notify skipped [err: %d, status: 0x%02X]", cmd, err, status_code);
     }
 }
 
 static void ble_notify_tracked_ctx_status(const ble_indicate_ctx_t *ctx, uint8_t status_code)
 {
     uint16_t cmd = ble_tracked_cmd_for_ctx(ctx);
     if (cmd != CMD_UNKNOWN) {
         ble_notify_tracked_cmd_status(cmd, status_code);
     }
 }
 
 esp_err_t ble_notify_send_logControl(const uint8_t *data, size_t len)
 {
     if (!data || len == 0) {
         return ESP_ERR_INVALID_ARG;
     }
 
     if (!g_logControl.enabled ||
         g_logControl.conn_handle == BLE_HS_CONN_HANDLE_NONE ||
         g_logControl.attr_handle == 0) {
         return ESP_ERR_INVALID_STATE;
     }
 
     struct os_mbuf *om = ble_hs_mbuf_from_flat(data, len);
     if (!om) {
         ESP_LOG_E(TAG, "ERROR: logControl notify (%d) mbuf alloc failed", g_logControl.attr_handle);
         return ESP_ERR_NO_MEM;
     }
 
     int rc = ble_gatts_notify_custom(g_logControl.conn_handle, g_logControl.attr_handle, om);
     if (rc != 0) {
         ESP_LOG_E(TAG, "ERROR: logControl notify (%d) failed [rc: %d]", g_logControl.attr_handle, rc);
         return ESP_FAIL;
     }
 
     return ESP_OK;
 }
 
 static void ble_command_process(uint16_t cmd, uint64_t value, char* buffer) {
     ESP_LOGN(TAG, "BLE - commG: CMD-0x%04X received", cmd);
 
     esp_err_t err = comm_execute(cmd, value, buffer);
     if (err != ESP_OK) {
         ESP_LOG_E(TAG, "BLE - commG: CMD-0x%04X failed [err: %d]",cmd, err);
     }
     ble_notify_send_commResponse(cmd, err);
 }
 
