 static int commGet_access_cb(uint16_t conn_handle, uint16_t attr_handle, struct ble_gatt_access_ctxt *ctxt, void *arg)
 {
     (void)conn_handle;
     (void)arg;
     if (attr_handle != commGet_handle) {
         ESP_LOG_E(TAG, "BLE - ERROR: unexpected attr_handle = %d", attr_handle);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     if (ctxt->op != BLE_GATT_ACCESS_OP_WRITE_CHR) {
         ESP_LOG_E(TAG, "BLE - ERROR: unsupported op = %d", ctxt->op);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     if (!ble_secure_is_authenticated()) {
         return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "commGet before auth");
     }
 
     uint16_t incoming_len = OS_MBUF_PKTLEN(ctxt->om);
     if (incoming_len == 0) {
         ESP_LOG_E(TAG, "BLE - commGet ERROR: empty payload");
         return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
     }
 
     uint8_t *chunk = (uint8_t *)malloc(incoming_len);
     if (!chunk) {
         ESP_LOG_E(TAG, "BLE - commGet ERROR: malloc chunk failed");
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     int rc = ble_hs_mbuf_to_flat(ctxt->om, chunk, incoming_len, &incoming_len);
     if (rc != 0) {
         ESP_LOG_E(TAG, "BLE - commGet ERROR: mbuf_to_flat [rc: %d]", rc);
         free(chunk);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     bool is_complete = false;
     rc = rcvMsg_feed(chunk, incoming_len, &is_complete);
 
     if (is_complete) {
         ble_secure_decoded_msg_t msg = {};
         esp_err_t err = ble_secure_decode_message(rcvMsg_buffer(), rcvMsg_len(), SEC_TYPE_COMM_GET_REQ, &msg);
         if (err != ESP_OK) {
             free(chunk);
             rcvMsg_reset();
             ble_secure_decoded_msg_free(&msg);
             return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "commGet secure decode failed");
         }
         ble_process_cloud_command((char*)msg.payload, msg.payload_len);
         ble_secure_decoded_msg_free(&msg);
         rcvMsg_reset();
     }
     
     free(chunk);
     if (rc != 0) {
         return rc;
     }
 
     return 0;
 }
 
 static int paramGet_access_cb(uint16_t conn_handle, uint16_t attr_handle, struct ble_gatt_access_ctxt *ctxt, void *arg)
 {
     (void)conn_handle;
     (void)arg;
     if (attr_handle != paramGet_handle) {
         ESP_LOG_E(TAG, "BLE - ERROR: unexpected attr_handle = %d", attr_handle);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     if (ctxt->op != BLE_GATT_ACCESS_OP_WRITE_CHR) {
         ESP_LOG_E(TAG, "BLE - ERROR: unsupported op = %d", ctxt->op);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     if (!ble_secure_is_authenticated()) {
         return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "paramGet before auth");
     }
 
     uint16_t incoming_len = OS_MBUF_PKTLEN(ctxt->om);
     if (incoming_len == 0) {
         ESP_LOG_E(TAG, "BLE - paramGet ERROR: empty payload");
         return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
     }
 
     uint8_t *chunk = (uint8_t *)malloc(incoming_len);
     if (!chunk) {
         ESP_LOG_E(TAG, "BLE - paramGet ERROR: malloc chunk failed");
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     int rc = ble_hs_mbuf_to_flat(ctxt->om, chunk, incoming_len, &incoming_len);
     if (rc != 0) {
         ESP_LOG_E(TAG, "BLE - paramGet ERROR: mbuf_to_flat [rc: %d]", rc);
         free(chunk);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     bool is_complete = false;
     rc = rcvMsg_feed(chunk, incoming_len, &is_complete);
     free(chunk);
     if (rc != 0) {
         return rc;
     }
 
     if (is_complete) {
         ble_secure_decoded_msg_t msg = {};
         esp_err_t sec_err = ble_secure_decode_message(rcvMsg_buffer(), rcvMsg_len(), SEC_TYPE_PARAM_GET_REQ, &msg);
         if (sec_err != ESP_OK) {
             rcvMsg_reset();
             ble_secure_decoded_msg_free(&msg);
             return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "paramGet secure decode failed");
         }
 
         char *resp_buf = NULL;
         esp_err_t err = process_sfy_config_json((char*)msg.payload, msg.payload_len, &resp_buf);
 
         rcvMsg_reset();
         ble_secure_decoded_msg_free(&msg);
 
         if (!resp_buf || err != ESP_OK) {
             return BLE_ATT_ERR_UNLIKELY;
         }
 
         if(getVerb() > 1) {
             ESP_LOGN(TAG, "BLE - paramGet: response...");
             ESP_LOGN(TAG, "[%s]", resp_buf);
         }
 
         if(ble_indicate_prepare_msg(&g_paramResponse, (uint8_t*)resp_buf, strlen(resp_buf)) != ESP_OK) {
             if(resp_buf) { free(resp_buf); }
         }
 
         ble_indicate_send_msg(&g_paramResponse);
 
         return 0;
     }
 
     return 0;
 }
 
 // Indicate module ======================================================================
 
 static ble_indicate_ctx_t *get_indicate_ctx(uint16_t attr_handle) {
     for (size_t i = 0; i < g_indicate_ctx_count; i++) {
         if (g_indicate_ctxs[i] && g_indicate_ctxs[i]->attr_handle == attr_handle) {
             return g_indicate_ctxs[i];
         }
     }
     return NULL;
 }
 
 static void ble_indicate_reset(ble_indicate_ctx_t *ctx) {
     ctx->tosend_buf = NULL;
     ctx->tosend_len = 0;
     ctx->tosend_offset = 0;
     ctx->tosend_chunk = 0;
     ctx->tosend_retries = 0;
     ctx->active = false;
     ctx->fragment = false;
     ctx->num_chunks = 0;
     ctx->chunk_len = 0;
     ctx->crc32 = 0;
 }
 
 static void ble_indicate_abort(ble_indicate_ctx_t *ctx) {
     if (ctx->tosend_buf) {
         free(ctx->tosend_buf);
         ctx->tosend_buf = NULL;
     }
 
     ble_indicate_reset(ctx);
 }
 
 static esp_err_t ble_indicate_prepare_msg(ble_indicate_ctx_t *ctx, uint8_t *buf, size_t len) {
     if (!ctx || !buf || len == 0) return ESP_ERR_INVALID_ARG;
 
     secure_type_t secure_type = ble_secure_indicate_type_for_ctx(ctx);
     if (secure_type != SEC_TYPE_AUTH_SYNC_RSP) {
         if (!ble_secure_is_authenticated()) {
             return ESP_ERR_INVALID_STATE;
         }
 
         uint8_t *secure_buf = NULL;
         size_t secure_len = 0;
         esp_err_t secure_err = ble_secure_encode_message(secure_type, buf, len, &secure_buf, &secure_len);
         if (secure_err != ESP_OK) {
             return secure_err;
         }
 
         free(buf);
         buf = secure_buf;
         len = secure_len;
     }
 
     if(ctx->active) {
         ble_indicate_abort(ctx);
     }
 
     ctx->tosend_buf = buf;
     ctx->tosend_len = len;
     ctx->tosend_offset = 0;
     ctx->tosend_chunk = 0;
     ctx->tosend_retries = 0;
     ctx->active = true;
 
     /* ATT_MTU - 3 (opcode + handle) = máximo payload por indicación */
     const size_t mtu_payload = ble_att_mtu(ctx->conn_handle) - 3;
     /* Cada chunk lleva cabecera: SEQ=;N=;LEN=;CRC=;F=<S/E/->; → restar overhead */
     const size_t chunk_overhead = BLE_INDICATE_CHUNK_HEADER_MAX;
     const size_t payload_per_chunk = (mtu_payload > chunk_overhead) ? (mtu_payload - chunk_overhead) : mtu_payload;
     const size_t safe_payload_per_chunk = (payload_per_chunk > BLE_INDICATE_MAX_CHUNK_PAYLOAD)
         ? BLE_INDICATE_MAX_CHUNK_PAYLOAD
         : payload_per_chunk;
 
     if (len > mtu_payload) {
         ESP_LOG_W(TAG, "BLE - INDICATE (%d): payload too long (%u > %u). Fragmenting...", ctx->attr_handle, len, mtu_payload);
         ctx->fragment = true;
         ctx->chunk_len = safe_payload_per_chunk;
         /* Usar un chunk conservador reduce cortes del peer en enlaces inestables. */
         ctx->num_chunks = (len + safe_payload_per_chunk - 1) / safe_payload_per_chunk;
         ctx->crc32 = esp_rom_crc32_le(0xFFFFFFFFu, buf, len);
     } else {
         ctx->fragment = false;
     }
 
     return ESP_OK;
 }
 
 /*
  * Construye un único chunk con cabecera SEQ=;N=;LEN=;CRC=;F=; + payload, listo para
  * ble_hs_mbuf_from_flat. El buffer devuelto debe liberarse con free().
  * out_len = longitud total (cabecera + payload). Si out_payload_len != NULL, se
  * escribe ahí los bytes de payload (para que el caller actualice tosend_offset).
  * Retorna NULL si no hay datos que enviar o error; *out_len = 0 en ese caso.
  */
 static uint8_t* ble_indicate_build_chunk(ble_indicate_ctx_t *ctx, size_t *out_len, size_t *out_payload_len) {
     if (!ctx || !out_len || !ctx->tosend_buf || ctx->tosend_offset >= ctx->tosend_len) {
         if (out_len) *out_len = 0;
         if (out_payload_len) *out_payload_len = 0;
         return NULL;
     }
 
     const size_t remaining = ctx->tosend_len - ctx->tosend_offset;
     const size_t payload_len = ctx->fragment
         ? (remaining < ctx->chunk_len ? remaining : ctx->chunk_len)
         : remaining;
 
     if (payload_len == 0) {
         *out_len = 0;
         if (out_payload_len) *out_payload_len = 0;
         return NULL;
     }
     if (out_payload_len) *out_payload_len = payload_len;
 
     uint32_t seq, n;
     uint32_t crc = ctx->crc32;
     char flag;
 
     if (ctx->fragment) {
         seq = (uint32_t)(ctx->tosend_offset / ctx->chunk_len);
         n = (uint32_t)ctx->num_chunks;
         if (seq == 0 && n > 1) {
             flag = (char)CHUNK_FLAG_START;
         } else if (seq == n - 1) {
             flag = (char)CHUNK_FLAG_END;
         } else {
             flag = (char)CHUNK_FLAG_MID;
         }
     } else {
         seq = 0;
         n = 1;
         flag = (char)CHUNK_FLAG_END;
         if (crc == 0) {
             crc = esp_rom_crc32_le(0xFFFFFFFFu, ctx->tosend_buf, ctx->tosend_len);
         }
     }
 
     size_t header_max = BLE_INDICATE_CHUNK_HEADER_MAX;
     size_t total = header_max + payload_len;
     uint8_t *buf = (uint8_t *)malloc(total);
     if (!buf) {
         *out_len = 0;
         if (out_payload_len) *out_payload_len = 0;
         return NULL;
     }
 
     int header_len = snprintf((char *)buf, header_max + 1,
         "SEQ=%lu;N=%lu;LEN=%u;CRC=%08lX;F=%c;",
         (unsigned long)seq,
         (unsigned long)n,
         (unsigned)ctx->tosend_len,
         (unsigned long)crc,
         (char)flag);
     if (header_len <= 0 || (size_t)header_len > header_max) {
         free(buf);
         *out_len = 0;
         if (out_payload_len) *out_payload_len = 0;
         return NULL;
     }
     memcpy(buf + header_len, ctx->tosend_buf + ctx->tosend_offset, payload_len);
     *out_len = (size_t)header_len + payload_len;
     return buf;
 }
 
 static void ble_indicate_send_msg(ble_indicate_ctx_t *ctx) {
     if (!ctx || !ctx->active ||
         !ctx->enabled ||
         ctx->conn_handle == BLE_HS_CONN_HANDLE_NONE) {
         return;
     }
 
     if (ctx->tosend_offset >= ctx->tosend_len) {
         // nada para enviar
         ble_indicate_abort(ctx);
         return;
     }
 
     /* Ya hay un indicate en vuelo; esperar callback antes de enviar otro. */
     if (ctx->tosend_chunk != 0) {
         return;
     }
 
     ESP_LOGN(TAG, "Enviando paquete (%d)", ctx->tosend_offset);
 
     struct os_mbuf *om = NULL;
     uint8_t *chunk_buf = NULL;
 
     if (ctx->fragment) {
         size_t chunk_len = 0, payload_len = 0;
         chunk_buf = ble_indicate_build_chunk(ctx, &chunk_len, &payload_len);
         if (!chunk_buf || chunk_len == 0) {
             ESP_LOG_E(TAG, "BLE - INDICATE (%d): build_chunk failed", ctx->attr_handle);
             if (chunk_buf) free(chunk_buf);
             ble_notify_tracked_ctx_status(ctx, (uint8_t)ESP_FAIL);
             ble_indicate_abort(ctx);
             return;
         }
         ctx->tosend_chunk = payload_len;
         om = ble_hs_mbuf_from_flat(chunk_buf, chunk_len);
         free(chunk_buf);
     } else {
         const size_t mtu_payload = ble_att_mtu(ctx->conn_handle) - 3;
         const size_t remaining = ctx->tosend_len - ctx->tosend_offset;
         const size_t chunk_len = (remaining > mtu_payload) ? mtu_payload : remaining;
         ctx->tosend_chunk = chunk_len;
         om = ble_hs_mbuf_from_flat(&ctx->tosend_buf[ctx->tosend_offset], chunk_len);
     }
 
     if (!om) {
         ESP_LOG_E(TAG, "BLE - INDICATE (%d): mbuf alloc failed", ctx->attr_handle);
         ble_notify_tracked_ctx_status(ctx, (uint8_t)ESP_ERR_NO_MEM);
         ble_indicate_abort(ctx);
         return;
     }
 
     int rc = ble_gatts_indicate_custom(ctx->conn_handle, ctx->attr_handle, om);
     if (rc != 0) {
         ESP_LOG_E(TAG, "BLE - INDICATE (%d): indicate failed [rc: %d]", ctx->attr_handle, rc);
 
         ctx->tosend_chunk = 0;
 
         ctx->tosend_retries++;
         if (ctx->tosend_retries > INDICATE_TX_MAX_RETRIES) {
             ESP_LOG_E(TAG, "BLE - INDICATE (%d): retries exhausted", ctx->attr_handle);
             ble_notify_tracked_ctx_status(ctx, (uint8_t)rc);
             ble_indicate_abort(ctx);
         }
         return;
     }
 }
 
 void ble_indicate_handler(uint16_t handle, int status) {
     ble_indicate_ctx_t *ctx = get_indicate_ctx(handle);
     if(ctx) {
         if (status == 0) {
             ESP_LOGN(TAG, "BLE - INDICATE (%d): ACK received", handle);
 
             ESP_LOGN(TAG, "BLE - INDICATE (%d): sent %u/%u (chunk=%u)", ctx->attr_handle,
              (unsigned)(ctx->tosend_offset + ctx->tosend_chunk),
              (unsigned)ctx->tosend_len,
              (unsigned)ctx->tosend_chunk);
 
             ctx->tosend_offset += ctx->tosend_chunk;
             ctx->tosend_chunk = 0;
             ctx->tosend_retries = 0;
 
             if (ctx->tosend_offset >= ctx->tosend_len) {
 
                 ble_notify_tracked_ctx_status(ctx, BLE_CMD_STATUS_OK);
 
                 free(ctx->tosend_buf);
                 ctx->tosend_buf = NULL;
 
                 if(handle == g_historySend.attr_handle) {
                     confirm_datapoint_send();
                 }
 
                 if (ctx->next_msg_cb == NULL) {
                     ctx->active = false;
                     return;   // 🔴 NO reencolar send_event
                 }
 
                 size_t tosend_len = 0;
                 uint8_t* tosend = ctx->next_msg_cb(&tosend_len);
                 if (!tosend) {
                     ctx->active = false;
                     return;   // 🔴 NO reencolar send_event
                 }
 
                 if (ble_indicate_prepare_msg(ctx, tosend, tosend_len) != ESP_OK) {
                     free(tosend);
                     ctx->active = false;
                     return;
                 }
             }
 
             /* Esperar a BLE_HS_EDONE antes de disparar el siguiente chunk. */
 
         } else if (status == BLE_HS_EDONE) {
             // Proceso GATT de indicate finalizado -> podemos ignorarlo
             ESP_LOGN(TAG, "BLE - INDICATE (%d): %sDONE%s", handle, LOG_COLOR_G, LOG_RESET_COLOR);
 
             if (ctx->active && ctx->enabled &&
                 ctx->conn_handle != BLE_HS_CONN_HANDLE_NONE &&
                 ctx->tosend_offset < ctx->tosend_len) {
                 ble_npl_eventq_put(nimble_port_get_dflt_eventq(), &ctx->send_event);
             }
         } else {
             if (status == BLE_HS_EBUSY) {
                 ESP_LOG_W(TAG, "BLE - INDICATE (%d): busy, waiting DONE", handle);
                 return;
             }
 
             if (status == BLE_HS_ENOMEM) {
                 ESP_LOG_W(TAG, "BLE - INDICATE (%d): no mem, waiting DONE", handle);
                 return;
             }
 
             if (status == BLE_HS_ENOTCONN) {
                 ESP_LOG_W(TAG, "BLE - INDICATE (%d): peer disconnected", handle);
                 ble_notify_tracked_ctx_status(ctx, (uint8_t)ESP_ERR_INVALID_STATE);
                 ble_indicate_abort(ctx);
                 return;
             }
 
             ESP_LOG_E(TAG, "BLE - INDICATE (%d): failed [rc: %d]", handle, status);
             
             ctx->tosend_retries++;
 
             if(ctx->tosend_retries > INDICATE_TX_MAX_RETRIES) {
                 ESP_LOG_E(TAG, "BLE - INDICATE (%d): aborting", handle);
                 ble_notify_tracked_ctx_status(ctx, (uint8_t)status);
                 ble_indicate_abort(ctx);
                 return;
             }
 
             ble_npl_eventq_put(nimble_port_get_dflt_eventq(), &ctx->send_event);
         }
     } else {
         ESP_LOG_E(TAG, "BLE - INDICATE (%d): can't get ctx", handle);
     }
 }
 
 static void ble_indicate_send_event_cb(struct ble_npl_event *ev)
 {
     ble_indicate_ctx_t *ctx = (ble_indicate_ctx_t *)ble_npl_event_get_arg(ev);
     ble_indicate_send_msg(ctx);
 }
 
 // ======================================================================================

