 static int authSync_access_cb(uint16_t conn_handle, uint16_t attr_handle, struct ble_gatt_access_ctxt *ctxt, void *arg)
 {
     (void)conn_handle;
     (void)arg;
 
     if (attr_handle != authSync_handle) {
         ESP_LOG_E(TAG, "BLE - AUTH ERROR: unexpected attr_handle = %d", attr_handle);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     if (ctxt->op == BLE_GATT_ACCESS_OP_READ_CHR) {
         uint8_t challenge[2 + BLE_SECURE_NONCE_LEN] = {0};
         size_t written_len = 0;
         int rc = ble_secure_build_auth_challenge(challenge, sizeof(challenge), &written_len);
         if (rc != 0) {
             return rc;
         }
         rc = os_mbuf_append(ctxt->om, challenge, written_len);
         if (rc != 0) {
             ESP_LOG_E(TAG, "BLE - AUTH ERROR: append challenge failed [rc: %d]", rc);
             return BLE_ATT_ERR_UNLIKELY;
         }
         return 0;
     }
 
     if (ctxt->op != BLE_GATT_ACCESS_OP_WRITE_CHR) {
         ESP_LOG_E(TAG, "BLE - AUTH ERROR: unsupported op = %d", ctxt->op);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     uint16_t incoming_len = OS_MBUF_PKTLEN(ctxt->om);
     if (incoming_len == 0) {
         return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
     }
 
     uint8_t *buf = (uint8_t *)malloc(incoming_len);
     if (!buf) {
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     int rc = ble_hs_mbuf_to_flat(ctxt->om, buf, incoming_len, &incoming_len);
     if (rc != 0) {
         free(buf);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     esp_err_t err = ble_secure_handle_auth_write(buf, incoming_len);
     free(buf);
     if (err != ESP_OK) {
         return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "auth sync write failed");
     }
 
     return 0;
 }
 
 static int commandGet_access_cb(uint16_t conn_handle, uint16_t attr_handle, struct ble_gatt_access_ctxt *ctxt, void *arg)
 {
     (void)conn_handle;
     (void)arg;
     if (attr_handle != commandGet_handle) {
         ESP_LOG_E(TAG, "BLE - ERROR: unexpected attr_handle = %d", attr_handle);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     if (ctxt->op != BLE_GATT_ACCESS_OP_WRITE_CHR) {
         ESP_LOG_E(TAG, "BLE - ERROR: unsupported op = %d", ctxt->op);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     if (!ble_secure_is_authenticated()) {
         return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "commandGet before auth");
     }
 
     uint16_t incoming_len = OS_MBUF_PKTLEN(ctxt->om);
     if (incoming_len == 0) {
         return BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN;
     }
 
     uint8_t *raw = (uint8_t *)malloc(incoming_len);
     if (!raw) {
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     int rc = ble_hs_mbuf_to_flat(ctxt->om, raw, incoming_len, &incoming_len);
     if (rc != 0) {
         free(raw);
         ESP_LOG_E(TAG, "BLE - commG ERROR: ble_hs_mbuf_to_flat [rc: %d]", rc);
         return BLE_ATT_ERR_UNLIKELY;
     }
 
     ble_secure_decoded_msg_t msg = {};
     esp_err_t sec_err = ble_secure_decode_message(raw, incoming_len, SEC_TYPE_COMMAND_GET_REQ, &msg);
     free(raw);
     if (sec_err != ESP_OK) {
         ble_secure_decoded_msg_free(&msg);
         return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "commandGet secure decode failed");
     }
 
     const uint8_t *buf = msg.payload;
     uint16_t len = msg.payload_len;
 
     if (len < 2) {
         ble_secure_decoded_msg_free(&msg);
         ESP_LOG_E(TAG, "BLE - commG ERROR: payload too short (%u)", len);
         return ble_secure_disconnect_and_return(BLE_ATT_ERR_INVALID_ATTR_VALUE_LEN, "commandGet payload too short");
     }
 
     uint16_t cmd = (uint16_t)buf[0] << 8 | buf[1];
     bool has_cmd_arg = len > 2;
     uint8_t cmd_arg = has_cmd_arg ? buf[2] : 0;
 
     switch (cmd) {
         case CMD_START_LOGS:
             ESP_LOGN(TAG, "BLE - commG: START-LOGS received");
             ESP_LOGN(TAG, "BLE - commG: START-LOGS ignored in current protocol (use log subscription)");
             ble_secure_decoded_msg_free(&msg);
             return 0;
 
         case CMD_STOP_LOGS:
             ESP_LOGN(TAG, "BLE - commG: STOP-LOGS received");
             ESP_LOGN(TAG, "BLE - commG: STOP-LOGS ignored in current protocol (use log unsubscription)");
             ble_secure_decoded_msg_free(&msg);
             return 0;
 
         case CMD_CTRL_BLINK:
             ble_command_process(CMD_CTRL_BLINK, has_cmd_arg ? cmd_arg : 10, NULL);
             ble_secure_decoded_msg_free(&msg);
             return 0;
 
         case CMD_CTRL_TEST:
         case CMD_CTRL_TEST_COMP:
         case CMD_CTRL_TEST_RES:
         case CMD_CTRL_TEST_FAN:
         case CMD_CTRL_TEST_LIGHT:
         case CMD_CTRL_TEST_ROUTINE:
             ble_command_process(cmd, has_cmd_arg ? cmd_arg : 0, NULL);
             ble_secure_decoded_msg_free(&msg);
             return 0;
 
         default:
             ESP_LOG_W(TAG, "BLE - commG: unknown cmd = 0x%02X", cmd);
             ble_secure_decoded_msg_free(&msg);
             return ble_secure_disconnect_and_return(BLE_ATT_ERR_UNLIKELY, "commandGet unknown cmd");
     }
 }
 
