         .type = BLE_GATT_SVC_TYPE_PRIMARY, // tipo de servicio: PRIMARIO (visible para el central)
         .uuid = &params_svc_uuid.u, // UUID de 128 bits
         .characteristics = (struct ble_gatt_chr_def[]) {
             // 6: PARAMETROS-GET
             {
                 .uuid = &paramGet_chr_uuid.u,
                 .access_cb = paramGet_access_cb,
                 .flags = BLE_GATT_CHR_F_WRITE,
                 .val_handle = &paramGet_handle,
             },
             // 7: PARAMETROS-RESPONSE
             {
                 .uuid = &paramResponse_chr_uuid.u,
                 .access_cb = paramReponse_access_cb,              // no se lee ni escribe
                 .flags = BLE_GATT_CHR_F_INDICATE,
                 .val_handle = &g_paramResponse.attr_handle,
             },
             { 0 },
         }
     },
 
     // Service: Debug
     {
         .type = BLE_GATT_SVC_TYPE_PRIMARY, // tipo de servicio: PRIMARIO (visible para el central)
         .uuid = &dbg_svc_uuid.u, // UUID de 128 bits
         .characteristics = (struct ble_gatt_chr_def[]) {
             // 5: LOG-SEND
             {
                 .uuid = &logSend_chr_uuid.u,   // UUID
                 .access_cb = logSend_access_cb,         // se ejecuta cuando el central hace un READ
                 .flags = BLE_GATT_CHR_F_NOTIFY, // lectura + notify
                 .val_handle = &g_logSend.attr_handle,  // handle
             },
             // LOG-TERMINAL
             {
                 .uuid = &logTerminal_chr_uuid.u,   // UUID
                 .access_cb = logTerminal_access_cb,         // se ejecuta cuando el central hace un READ
                 .flags = BLE_GATT_CHR_F_NOTIFY, // lectura + notify
                 .val_handle = &g_logTerminal.attr_handle,  // handle
             },
             { 0 },
         }
     },
 
     {
         0, /* No more services. */
     },
 };
 
 /*
  *  GATT server initialization
  *      1. Initialize GATT service
  *      2. Update NimBLE host GATT services counter
  *      3. Add GATT services to server
  */
 int gatt_svc_init(void) {
     /* Local variables */
     int rc;
 
     g_indicate_ctx_count = 0;
     g_notify_ctx_count = 0;
     memset(g_indicate_ctxs, 0, sizeof(g_indicate_ctxs));
     memset(g_notify_ctxs, 0, sizeof(g_notify_ctxs));
 
     // Inicializo GATT service
     ble_svc_gatt_init();
 
     // Cuenta y reserva memoria para los servicios, caracteristicas y descriptores del servidor
     rc = ble_gatts_count_cfg(gatt_services);
     if (rc != 0) {
         return rc;
     }
 
     // Agrega servicios al servidor
     rc = ble_gatts_add_svcs(gatt_services);
     if (rc != 0) {
         return rc;
     }
 
     if (!s_gatt_runtime_inited) {
         ble_npl_event_init(&g_historySend.send_event,
                        ble_indicate_send_event_cb,
                        &g_historySend);
     }
     g_indicate_ctxs[0] = &g_historySend;
     g_indicate_ctx_count++;
 
     if (!s_gatt_runtime_inited) {
         ble_npl_event_init(&g_paramResponse.send_event,
                        ble_indicate_send_event_cb,
                        &g_paramResponse);
     }
     g_indicate_ctxs[1] = &g_paramResponse;
     g_indicate_ctx_count++;
 
     if (!s_gatt_runtime_inited) {
         ble_npl_event_init(&g_metadataRead.send_event,
                        ble_indicate_send_event_cb,
                        &g_metadataRead);
     }
     g_indicate_ctxs[2] = &g_metadataRead;
     g_indicate_ctx_count++;
 
     if (!s_gatt_runtime_inited) {
         ble_npl_event_init(&g_diagnosisRead.send_event,
                        ble_indicate_send_event_cb,
                        &g_diagnosisRead);
     }
     g_indicate_ctxs[3] = &g_diagnosisRead;
     g_indicate_ctx_count++;
 
     if (!s_gatt_runtime_inited) {
         ble_npl_callout_init(&g_logSend.callout,
                              nimble_port_get_dflt_eventq(),
                              ble_notify_tick_cb,
                              &g_logSend);
         ble_npl_callout_init(&g_logTerminal.callout,
                              nimble_port_get_dflt_eventq(),
                              ble_notify_tick_cb,
                              &g_logTerminal);
         s_gatt_runtime_inited = true;
     }
     g_notify_ctxs[0] = &g_logSend;
     g_notify_ctx_count++;
 
     g_notify_ctxs[1] = &g_commResponse;
     g_notify_ctx_count++;
 
     g_notify_ctxs[2] = &g_logControl;
     g_notify_ctx_count++;
 
     g_notify_ctxs[3] = &g_dataStatus;
     g_notify_ctx_count++;
 
     g_notify_ctxs[4] = &g_logTerminal;
     g_notify_ctx_count++;
 
     return 0;
 }
 
 // Se setea en nimble_host_config_init. Solo imprime cosas
 void gatt_svr_register_cb(struct ble_gatt_register_ctxt *ctxt, void *arg) {
     /* Local variables */
     char buf[BLE_UUID_STR_LEN];
 
     /* Handle GATT attributes register events */
     switch (ctxt->op) {
 
     /* Service register event */
     case BLE_GATT_REGISTER_OP_SVC:
         ESP_LOGD(TAG, "registered service %s with handle=%d",
                  ble_uuid_to_str(ctxt->svc.svc_def->uuid, buf),
                  ctxt->svc.handle);
