 static ble_notify_ctx_t *get_notify_ctx_by_handle(uint16_t attr_handle)
 {
     for (size_t i = 0; i < g_notify_ctx_count; i++) {
         if (g_notify_ctxs[i] && g_notify_ctxs[i]->attr_handle == attr_handle) {
             return g_notify_ctxs[i];
         }
     }
     return NULL;
 }
 
 static secure_type_t ble_secure_indicate_type_for_ctx(const ble_indicate_ctx_t *ctx)
 {
     if (ctx == &g_metadataRead) {
         return SEC_TYPE_METADATA_RSP;
     }
     if (ctx == &g_historySend) {
         return SEC_TYPE_HISTORY_RSP;
     }
     if (ctx == &g_diagnosisRead) {
         return SEC_TYPE_DIAGNOSIS_RSP;
     }
     if (ctx == &g_paramResponse) {
         return SEC_TYPE_PARAM_RESPONSE_RSP;
     }
     return SEC_TYPE_AUTH_SYNC_RSP;
 }

 static secure_type_t ble_secure_notify_type_for_ctx(const ble_notify_ctx_t *ctx)
 {
     if (ctx == &g_commResponse) {
         return SEC_TYPE_COMMANDS_RSP;
     }
     if (ctx == &g_dataStatus) {
         return SEC_TYPE_DATA_STATUS_RSP;
     }
     if (ctx == &g_logControl) {
         return SEC_TYPE_LOG_CONTROL_RSP;
     }
     if (ctx == &g_logSend) {
         return SEC_TYPE_LOG_SEND_RSP;
     }
     if (ctx == &g_logTerminal) {
         return SEC_TYPE_LOG_TERMINAL_RSP;
     }
     return SEC_TYPE_AUTH_SYNC_RSP;
 }
 
 static int ble_secure_disconnect_and_return(int rc, const char *reason)
 {
     ESP_LOG_E(TAG, "BLE secure failure: %s", reason ? reason : "unknown");
     ble_secure_disconnect_active();
     rcvMsg_reset();
     return rc;
 }

 static esp_err_t ble_notify_send_secure_frame(ble_notify_ctx_t *ctx, secure_type_t type, const uint8_t *data, size_t len)
 {
     if (!ctx || !data || len == 0) {
         return ESP_ERR_INVALID_ARG;
     }
     if (!ctx->enabled || ctx->conn_handle == BLE_HS_CONN_HANDLE_NONE) {
         return ESP_ERR_INVALID_STATE;
     }
     if (!ble_secure_is_authenticated()) {
         return ESP_ERR_INVALID_STATE;
     }

     uint8_t *secure_payload = NULL;
     size_t secure_len = 0;
     esp_err_t err = ble_secure_encode_message(type, data, len, &secure_payload, &secure_len);
     if (err != ESP_OK) {
         return err;
     }

     struct os_mbuf *om = ble_hs_mbuf_from_flat(secure_payload, secure_len);
     if (!om) {
         free(secure_payload);
         return ESP_ERR_NO_MEM;
     }

     int rc = ble_gatts_notify_custom(ctx->conn_handle, ctx->attr_handle, om);
     free(secure_payload);
     return rc == 0 ? ESP_OK : ESP_FAIL;
 }
 
 static void ble_notify_tick_cb(struct ble_npl_event *ev)
 {
     ble_notify_ctx_t *ctx = (ble_notify_ctx_t *)ble_npl_event_get_arg(ev);
     if (!ctx || !ctx->active || !ctx->enabled ||
         ctx->conn_handle == BLE_HS_CONN_HANDLE_NONE || !ctx->next_msg_cb) {
         return;
     }
 
     bool sent_any = false;
     uint8_t max_to_send = ctx->max_per_interval;
 
     while (max_to_send > 0) {
         max_to_send--;
         size_t len = 0;
         uint8_t *data = ctx->next_msg_cb(&len);
 
         if (!data || len == 0) {
             break;
         }

         secure_type_t secure_type = ble_secure_notify_type_for_ctx(ctx);
         int rc = 0;
         if (secure_type == SEC_TYPE_AUTH_SYNC_RSP) {
             struct os_mbuf *om = ble_hs_mbuf_from_flat(data, len);
             if (!om) {
                 ESP_LOG_E(TAG, "ERROR: notify (%d) mbuf alloc failed", ctx->attr_handle);
                 free(data);
                 break;
             }

             rc = ble_gatts_notify_custom(ctx->conn_handle, ctx->attr_handle, om);
             if (rc != 0) {
                 ESP_LOG_E(TAG, "ERROR: notify (%d) failed [rc: %d]", ctx->attr_handle, rc);
                 free(data);
                 break;
             }
         } else {
             esp_err_t err = ble_notify_send_secure_frame(ctx, secure_type, data, len);
             if (err != ESP_OK) {
                 ESP_LOG_E(TAG, "ERROR: secure notify (%d) failed [err: %d]", ctx->attr_handle, err);
                 free(data);
                 break;
             }
         }

         free(data);
         sent_any = true;
     }
 
     if (sent_any) {
         ESP_LOG_I(TAG, "BLE - NOTIFY (%d) batch sent. Next send in %" PRIu32" ms", ctx->attr_handle, ctx->interval_ms);
     }
 
     ble_npl_callout_reset(&ctx->callout,
                           ble_npl_time_ms_to_ticks32(ctx->interval_ms));
 }
 
 static esp_err_t ble_notify_send_commResponse(uint16_t cmd, uint8_t err_code)
 {
     if (!g_commResponse.enabled ||
         g_commResponse.conn_handle == BLE_HS_CONN_HANDLE_NONE) {
         return ESP_ERR_INVALID_STATE;
     }
 
     uint8_t payload[3];
     payload[0] = (uint8_t)((cmd >> 8) & 0xFF);
     payload[1] = (uint8_t)(cmd & 0xFF);
     payload[2] = err_code;
 
     esp_err_t err = ble_notify_send_secure_frame(&g_commResponse, SEC_TYPE_COMMANDS_RSP, payload, sizeof(payload));
     if (err != ESP_OK) {
         ESP_LOG_E(TAG, "ERROR: commResponse notify (%d) failed [err: %d]", g_commResponse.attr_handle, err);
         return err;
     }

     return ESP_OK;
 }
 
 static esp_err_t ble_notify_send_dataStatus(uint16_t cmd, uint8_t err_code)
 {
     if (!g_dataStatus.enabled ||
         g_dataStatus.conn_handle == BLE_HS_CONN_HANDLE_NONE) {
         return ESP_ERR_INVALID_STATE;
     }
 
     uint8_t payload[3];
     payload[0] = (uint8_t)((cmd >> 8) & 0xFF);
     payload[1] = (uint8_t)(cmd & 0xFF);
     payload[2] = err_code;
 
     esp_err_t err = ble_notify_send_secure_frame(&g_dataStatus, SEC_TYPE_DATA_STATUS_RSP, payload, sizeof(payload));
     if (err != ESP_OK) {
         ESP_LOG_E(TAG, "ERROR: dataStatus notify (%d) failed [err: %d]", g_dataStatus.attr_handle, err);
         return err;
     }

     return ESP_OK;
 }
 
 static uint16_t ble_tracked_cmd_for_ctx(const ble_indicate_ctx_t *ctx)
 {
     if (ctx == &g_metadataRead) {
         return CMD_METADATA_READ;
     }
     if (ctx == &g_diagnosisRead) {
         return CMD_CONNECTIVITY_READ;
     }
     if (ctx == &g_paramResponse) {
         return CMD_PARAMS_READ;
     }
     return CMD_UNKNOWN;
 }
 
 static bool ble_is_tracked_read_cmd(uint16_t cmd)
 {
     return cmd == CMD_METADATA_READ ||
            cmd == CMD_CONNECTIVITY_READ ||
            cmd == CMD_PARAMS_READ;
 }
 
 static void ble_notify_tracked_cmd_status(uint16_t cmd, uint8_t status_code)
 {
     if (!ble_is_tracked_read_cmd(cmd)) {
         return;
     }
 
     esp_err_t err = ble_notify_send_dataStatus(cmd, status_code);
     if (err != ESP_OK) {
         ESP_LOG_W(TAG, "BLE - cmd 0x%04X status notify skipped [err: %d, status: 0x%02X]", cmd, err, status_code);
     }
 }
 
 static void ble_notify_tracked_ctx_status(const ble_indicate_ctx_t *ctx, uint8_t status_code)
 {
     uint16_t cmd = ble_tracked_cmd_for_ctx(ctx);
     if (cmd != CMD_UNKNOWN) {
         ble_notify_tracked_cmd_status(cmd, status_code);
     }
 }
 
 esp_err_t ble_notify_send_logControl(const uint8_t *data, size_t len)
 {
     if (!data || len == 0) {
         return ESP_ERR_INVALID_ARG;
     }
 
     if (!g_logControl.enabled ||
         g_logControl.conn_handle == BLE_HS_CONN_HANDLE_NONE ||
         g_logControl.attr_handle == 0) {
         return ESP_ERR_INVALID_STATE;
     }
 
     esp_err_t err = ble_notify_send_secure_frame(&g_logControl, SEC_TYPE_LOG_CONTROL_RSP, data, len);
     if (err != ESP_OK) {
         ESP_LOG_E(TAG, "ERROR: logControl notify (%d) failed [err: %d]", g_logControl.attr_handle, err);
         return err;
     }

     return ESP_OK;
 }
 
 static void ble_command_process(uint16_t cmd, uint64_t value, char* buffer) {
     ESP_LOGN(TAG, "BLE - commG: CMD-0x%04X received", cmd);
 
     esp_err_t err = comm_execute(cmd, value, buffer);
     if (err != ESP_OK) {
         ESP_LOG_E(TAG, "BLE - commG: CMD-0x%04X failed [err: %d]",cmd, err);
     }
     ble_notify_send_commResponse(cmd, err);
 }
 
