{
    return status == QuectelModem::REG_OK_HOME || status == QuectelModem::REG_OK_ROAMING;
}

static const char* main_reg_status_to_string(QuectelModem::RegStatus status)
{
    switch (status) {
    case QuectelModem::REG_OK_HOME: return "home";
    case QuectelModem::REG_OK_ROAMING: return "roaming";
    case QuectelModem::REG_SEARCHING: return "searching";
    case QuectelModem::REG_DENIED: return "denied";
    case QuectelModem::REG_UNREGISTERED: return "unregistered";
    case QuectelModem::REG_NO_RESULT:
    case QuectelModem::REG_UNKNOWN:
    default: return "unknown";
    }
}

static const char* main_rat_to_string(QuectelModem::rat_t rat)
{
    switch (rat) {
    case QuectelModem::GSM: return "GSM";
    case QuectelModem::CATM1: return "CATM1";
    case QuectelModem::CATNB1: return "CATNB1";
#if defined(CONFIG_SENSIFY_MODEM_EG912)
    case QuectelModem::LTE: return "CAT1BIS";
#endif
    case QuectelModem::NO_SERVICE:
    default: return "NONE";
    }
}

static const char* main_get_init_stage(bool& completed)
{
    completed = false;

    if (!controller_initialized || !controller_thread_started) {
        return "CONTROLLER_INIT";
    }

    if (iwifi().is_started() && !iwifi().is_active() && !ModemSetup::is_done()) {
        return "WIFI_CONNECT";
    }

    if (!ModemSetup::is_done() && !iwifi().is_active()) {
        return "MODEM_INIT";
    }

    if (mqtt != nullptr && mqtt->getConnectionState() == MQTT::MQTT_STATE_CONNECTING) {
        return "MQTT_CONNECT";
    }

    if (mqtt != nullptr && mqtt->getConnectionState() == MQTT::MQTT_STATE_CONNECTED) {
        if (!SfyParameters::isDeviceLinked()) {
            return "DEVICE_NOT_LINKED";
        }

        if (!cloud.is_started() || cloud.getLoopState() != CloudLogic::RUNNING) {
            return "CLOUD_SYNC";
        }

        completed = true;
        return "READY";
    }

    if (iwifi().is_active()) {
        Time_sync* time_sync = Time_sync::getInstance();
        if (time_sync != nullptr && !time_sync->isSynchronized()) {
            return "TIME_SYNC";
        }
        return "MQTT_SETUP";
    }

    return "NETWORK_CONNECT";
}

