/**
 * Actualiza mfg_buf/mfg_len con los datos devueltos por get_data_from_ram.
 * Si get_data_from_ram devuelve NULL, no se modifica nada (no se tocan los adv fields).
 * @return true si el contenido cambió y se actualizó mfg_buf/mfg_len; false si no hubo cambios.
 */
static bool update_mfg_from_ram(void) {
    size_t len = 0;
    uint8_t *p = get_data_from_ram(&len);
    if (p != NULL && len > 0) {
        const size_t max_payload_len = (size_t)MFG_DATA_MAX - 1;
        size_t copy_len = (len > max_payload_len) ? max_payload_len : len;
        uint8_t candidate_len = (uint8_t)(copy_len + 1);
        uint8_t candidate_buf[MFG_DATA_MAX];
        memcpy(candidate_buf, p, copy_len);
        candidate_buf[copy_len] = adv_indicator;

        /* No setear nada si el paquete no cambió */
        if (mfg_len == candidate_len && memcmp(mfg_buf, candidate_buf, candidate_len) == 0) {
            delete[] p;
            return false;
        }
        memcpy(mfg_buf, candidate_buf, candidate_len);
        mfg_len = candidate_len;
        delete[] p;
        return true;
    } else if(mfg_force_refresh_from_cache) {
        ESP_LOG_I(TAG, "Force refresh from cache");
        mfg_force_refresh_from_cache = false;
        if (mfg_len == 0) {
            return false;
        }
        uint8_t idx = mfg_len - 1;
        if (mfg_buf[idx] == adv_indicator) {
            return false;
        }
        mfg_buf[idx] = adv_indicator;
        return true;
    }
    /* get_data_from_ram devolvió NULL: no tocar mfg_buf/mfg_len ni los adv fields */
    return false;
}

