void confirm_datapoint_send() {
    if(history_send.active){
        SfyData::setPendingFromStorage();
        history_send.sent++;
        ESP_LOGN(TAG, "BLE - DATA: sent %" PRIu32 " of %" PRIu32 "", history_send.sent, history_send.count);
    } else {
        history_send.active = true;
        ESP_LOGN(TAG, "BLE - DATA: history send started");
    }
}

uint8_t* get_data_from_ram(size_t *len)
{
    if (!len) {
        return NULL;
    }

    Payload::payload_t data;
    if(!SfyData::peekLast(data)) {
        return NULL;
    }

    uint8_t buffer[SfyData::BINARY_BUFFER_SIZE];
    size_t size = 0;
    esp_err_t err = SfyData::toBinary(&data, 0, 0, buffer, &size);
    if (err != ESP_OK || size == 0) {
        ESP_LOG_E(TAG, "BLE - DATA: toBinary failed, err=%d, size=%u", err, (unsigned)size);
        return NULL;
    }

    uint8_t* out = (uint8_t*)malloc(size);
    if (out == NULL) {
        ESP_LOG_E(TAG, "BLE - DATA: malloc failed in get_data_from_ram");
        return NULL;
    }

    memcpy(out, buffer, size);

    *len = size;
    return out;
}

